comms.text:
@1 וַחֲזָא בָּלָק בַּר צִפּוֹר יָת כָּל דִי עֲבַד יִשְׂרָאֵל לֶאֱמוֹרָאֵי:
@2 וּדְחִיל מוֹאֲבָאָה מִן קֳדָם עַמָא לַחֲדָא אֲרֵי סַגִי הוּא וַעֲקַת לְמוֹאֲבָאָה מִן קֳדָם בְּנֵי יִשְׂרָאֵל:
@3 וַאֲמַר מוֹאָב לְסָבֵי מִדְיָן כְּעַן יְשֵׁיצוּן קְהָלָא יָת כָּל סַחֲרָנָנָא כְּמָא דִמְלַחֵיךְ תּוֹרָא יָת יְרוֹקָא דְחַקְלָא וּבָלָק בַּר צִפּוֹר מַלְכָּא לְמוֹאָב בְּעִידָנָה הַהִיא:
@4 וּשְׁלַח אִזְגַדִין לְוָת בִּלְעָם בַּר בְּעוֹר לִפְּתוֹר אֲרָם דְעַל פְּרָת אֲרַע בְּנֵי עַמֵיהּ לְמִקְרֵי לֵיהּ לְמֵימָר הָא עַמָא נְפַק מִמִצְרַיִם הָא חֲפָא יַת עֵין שִׁמְשָׁא דְאַרְעָא וְהוּא שָׁרֵי מִלְקִבְלִי:
@5 וּכְעַן אִיתָא כְּעַן לוֹט לִי יָת עַמָא הָדֵין אֲרֵי תַקִיף הוּא מִנִי מָאִים אֵכוּל לְאַגָחָא בֵּיהּ קְרָב וַאֲתָרֵכִינֵיהּ מִן אַרְעָא אֲרֵי יְדַעֲנָא יָת דִי תְבָרַךְ מְבָרָךְ וְדִי תְלוֹט לִיט:
@6 וַאֲזָלוּ סָבֵי מוֹאָב וְסָבֵי מִדְיָן וְקִסְמַיָא בִּידֵיהוֹן וַאֲתוֹ לְוַת בִּלְעָם וּמַלִילוּ עִמֵיהּ פִּתְגָמֵי בָּלָק:
@7 וַאֲמַר לְהוֹן בִּיתוּ הָכָא בְּלֵילְיָא וְאָתֵב יַתְכוֹן פִּתְגָמָא כְּמָא דִי יְמַלֵיל יְיָ עִמִי וְאוֹרִיכוּ רַבְרְבֵי מוֹאָב עִם בִּלְעָם:
@8 וַאֲתָא מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר מָן גוּבְרַיָא הָאִלֵין דְעִמָךְ:
@9 וַאֲמַר בִּלְעָם קֳדָם יְיָ בָּלָק בַּר צִפּוֹר מַלְכָּא דְמוֹאָב שְׁלַח לְוָתִי:
@10 הָא עַמָא דִי נְפַק מִמִצְרַיִם וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא כְּעַן אִיתָא לוֹט לִי יָתֵיהּ מָאִים אֵיכוּל לְאַגָחָא בֵּיהּ קְרָב וְאֲתָרֵיכִינֵיהּ:
@11 וַאֲמַר יְיָ לְבִלְעָם לָא תֵיזִיל עִמְהוֹן לָא תְלוֹט יָת עַמָא אֲרֵי בְרִיךְ הוּא:
@12 וְקָם בִּלְעָם בְּצַפְרָא וַאֲמַר לְרַבְרְבֵי בָלָק אִיזִילוּ לְאַרְעֲכוֹן אֲרֵי לֵית רַעֲוָא קֳדָם יְיָ לְמִשְׁבְּקִי לְמֵיזַל עִמְכוֹן:
@13 וְקָמוּ רַבְרְבֵי מוֹאָב וַאֲתוֹ לְוָת בָּלָק וַאֲמָרוּ סָרֵיב בִּלְעָם לְמֵיתֵי עִמָנָא:
@14 וְאוֹסִיף עוֹד בָּלָק לְמִשְׁלַח רַבְרְבִין סַגִיאִין:ויַקִירִין מֵאִלֵין:
@15 וַאֲתוֹ לְוָת בִּלְעָם וַאֲמָרוּ לֵיהּ כִּדְנַן אֲמַר בָּלָק בַּר צִפּוֹר לָא כְעַן תִּתְמְנַע מִלְמֵיתֵי לְוָתִי:
@16 אֲרֵי יְקָרָא אֲיַקְרִינָךְ לַחֲדָא וְכֹל דִי תֵימַר לִי אַעְבֵּד וְאִיתָא כְעַן לוֹט לִי יַת עַמָא הָדֵין:
@17 וַאֲתֵיב בִּלְעָם וַאֲמַר לְעַבְדֵי בָלָק אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ אֱלָהָי לְמֶעְבַּד זְעֵרְתָּא אוֹ רַבְּתָא:
@18 וּכְעַן אוֹרִיכוּ כְעַן הָכָא אַף אַתּוּן בְּלֵילְיָא וְאִדַע מָה יוֹסֵף יְיָ לְמַלָלָא עִמִי:
@19 וַאֲתָּא מֵימַר מִן קֳדָם יְיָ לְבִלְעָם בְּלֵילְיָא וַאֲמַר לֵיהּ אִם לְמִקְרֵי לָךְ אֲתוֹ גֻבְרַיָא קוּם אִיזֵיל עִמְהוֹן וּבְרַם יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תַּעְבֵיד:
@20 וְקָם בִּלְעָם בְּצַפְרָא וְזָרֵיז יַת אֲתָנֵיהּ וַאֲזַל עִם רַבְרְבֵי מוֹאָב:
@21 וּתְקֵיף רָגְזָא דַיְיָ אֲרֵי אָזֵיל הוּא וְאִתְעַתַּד מַלְאָכָא דַיְיָ בְּאוֹרְחָא לְשָׂטָן לֵהּ וְהוּא רָכִיב עַל אַתָּנֵיהּ וּתְרֵין עוּלֵימוֹהִי עִמֵהּ:
@22 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִּידֵיהּ וּסְטַת אֲתָּנָא מִן אוֹרְחָא וַאֲזָלַת בְּחַקְלָא וּמְחָא בִּלְעָם יַת אֲתָּנָא לְאַסְטָיוּתַהּ לְאָרְחָא:
@23 וְקָם מַלְאָכָא דַיְיָ בִּשְׁבִיל כַּרְמַיָא אַתְרָא דְגָדֵירָא מִכָּא וְגָדֵירָא מִכָּא:
@24 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וְאִדְחֵיקַת לְכָתְלָא וּדְחֵיקַת יַת רִגְלָא דְבִלְעָם לְכָתְלָא וְאוֹסִיף לְמִמְחַהּ:
@25 וְאוֹסֵף מַלְאָכָא דַיְיָ לְמֶעְבָּר וְקָם בַּאֲתַר עָק דִי לֵית אֹרַח לְמִסְטֵי לְיַמִינָא וְלִשְׂמָאלָא:
@26 וַחֲזַת אֲתָּנָא יַת מַלְאָכָא דַיְיָ וּרְבָעַת תְּחוֹת בִּלְעָם וּתְקֵיף רוּגְזָא דְבִלְעָם וּמְחָא יַת אֲתָּנָא בְּחֻטְרָא:
@27 וּפְתַח יְיָ יַת פּוּמָא דַאֲתָּנָא וַאֲמָרַת לְבִּלְעָם מָה עֲבָדִית לָךְ אֲרֵי מְחִיתַנִי דְנַן תְּלַת זִמְנִין:
@28 וַאֲמַר בִּלְעָם לַאֲתָּנָא אֲרֵי חַיִיכְתְּ בִּי אִלוּפוֹן אִית חַרְבָּא בִּידִי אֲרֵי כְעָן קְטַלְתִּיךְ:
@29 וַאֲמָרַת אֲתָּנָא לְבִלְעָם הֲלָא אֲנָא אֲתָּנָךְ דְרָכַבְתְּ עֲלַי מִדְאִיתָךְ עַד יוֹמָא הָדֵין הֲמֵילַף אַלִפְנָא לְמֶעֱבַּד לָךְ כְּדֵין וַאֲמַר לָא:
@30 וּגְלָא יְיָ יַת עֵינֵי בִלְעָם וַחֲזָא יַת מַלְאָכָא דַיְיָ מְעַתַּד בְּאָרְחָא וְחַרְבֵּיהּ שְׁלִיפָא בִידֵיהּ וּכְרַע וּסְגִיד לְאַפּוֹהִי:
@31 וַאֲמַר לֵיהּ מַלְאָכָא דַיְיָ עַל מָה מָחִיתָא יַת אֲתָּנָךְ דְנַן תְּלַת זִמְנִין הָא אֲנָא נְפָקִית לְמִשְׂטַן אֲרֵי גְלֵי קֳדָמַי דְאַתְּ רָעֵי לְמֵיזַל בְּאוֹרְחָא לְקִבְּלִי:
@32 וַחֲזַתְנִי אֲתָּנָא וּסְטַת מִן קֳדָמַי דְנַן תְּלַת זִמְנִין אִילוּפוֹן לָא סְטַּת מִן קֳדָמַי אֲרֵי כְעַן אַף יָתָךְ קְטָלִית וְיָתַהּ קַיֵימִית:
@33 וַאֲמַר בִּלְעָם לְמַלְאָכָה דַיְיָ חָבִית אֲרֵי לָא יְדָעִית אֲרֵי אַתְּ מְעַתֵּד לָקֳדָמוּתִי בְּאָרְחָא וּכְעַן אִם בִּישׁ בְּעֵינָךְ אֵיתוּב לִי:
@34 וַאֲמַר מַלְאָכָא דַיְיָ לְבִלְעָם אִיזֵיל עִם גוּבְרַיָא וּלְחוֹד יַת פִּתְגָמָא דִי אֲמַלֵיל עִמָךְ יָתֵיהּ תְּמַלֵיל וַאֲזַל בִּלְעָם עִם רַבְרְבֵי בָּלָק:
@35 וּשְׁמַע בָּלָק אֲרֵי אָתָא בִלְעָם וּנְפַק לָקֳדָמוּתֵה לְקַרְתָּא דְמוֹאָב דִי עַל תְּחוּם אַרְנוֹן דִי בִּסְטַר תְּחוּמָא:
@36 וַאֲמַר בָּלָק לְבִלְעָם הֲלָא מִשְׁלַח שַׁלְחִית לְוָתָךְ לְמִקְרֵי לָךְ לְמָא לָא אֲתֵיתָא לְוָתִי הַבְקוּשְׁטָא הֲוֵיתָא אָמַר לֵית אֲנָא יָכִיל לְיַקְרוּתָךְ:
@37 וַאֲמַר בִּלְעָם לְבָלָק הָא אֲתֵיתִי לְוָתָךְ כְּעַן הֲמֵיכַל יְכִלְנָא לְמַלָלָא מִדַעַם פִּתְגָמָא דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֲמַלֵיל:
@38 וַאֲזַל בִּלְעָם עִם בָּלָק וַאֲתוֹ לְקִרְיַת מְחוֹזוֹהִי:
@39 וּנְכֵיס בָּלָק תּוֹרִין וְעָאן וּשְׁלַח לְבִלְעָם וּלְרַבְרְבַיָא דִי עִמֵיהּ:
@40 וַהֲוָה בְּצַפְרָא וּדְבַר בָּלָק יַת בִּלְעָם וְאַסְקֵיהּ לְרָמַת דַחַלְתֵּיהּ וַחֲזָא מִתַּמָן קְצַת מִן עַמָא:
@41 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@42 וַעֲבַד בָּלָק כְּמָא דִי מַלֵיל בִּלְעָם וְאַסֵיק בָּלָק וּבִלְעָם תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@43 וַאֲמַר בִּלְעָם לְבָלָק אִתְעַתֵּד עַל עֲלָתָךְ וְאֵיהַךְ מָאִים יְעָרַע מֵימַר מִן קֳדָם יְיָ לָקֳדָמוּתִי וּפִתְגָמָא דְיַחֲזִנַנִי וְאֵחַוֵי לָךְ וַאֲזַל יְחִידִי:
@44 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְוַת בִּלְעָם וַאֲמַר לֵיהּ יַת שַׁבְעָא מַדְבְּחִין סְדָרִית וְאַסֵקִית תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@45 וְשַׁוִי יְיָ פִּתְגָמָא בְּפוּמָא דְבִלְעָם וַאֲמַר תּוּב לְוַת בָּלָק וּכְדֵין תְּמַלֵיל:
@46 וְתַב לְוָתֵיהּ וְהָא מְעַתֵּד עַל עֲלָתֵיהּ הוּא וְכָל רַבְרְבֵי מוֹאָב:
@47 וּנְטַל מַתְלֵיהּ וַאֲמַר מִן אֲרָם דַבְּרַנִי בָלָק מַלְכָּא דְמוֹאָב מִטוּרֵי מַדִנְחָא אִיתָא לוֹטּ לִי יַעֲקֹב וְאִיתָא תָּרֵיךְ לִי יִשְׂרָאֵל:
@48 מָה אֲלוֹטֵיהּ דְלָא לַטְיֵהּ אֵל וּמָה אֲתָרְכֵיהּ דְלָא תָרְכֵיהּ יְיָ:
@49 אֲרֵי מֵרֵישׁ טוּרַיָא חֲזִיתֵיהּ וּמֵרָמָתָא סְכִיתֵיהּ הָא עַמָא בִּלְחוֹדֵיהוֹן עֲתִידִין דְיַחְסְנוּן עַלְמָא וּבְעַמְמַיָא לָא יִתְדְנוּן גְמִירָא:
@50 מָן יֵיכוֹל לְמִמְנֵי דַעַדְקַיָא דְבֵית יַעֲקֹב דְאָמִיר עֲלֵיהוֹן יִסְגוּן כְּעַפְרָא דְאַרְעָא אוֹ חֲדָא מֵאַרְבַּע מַשִׁרְיָתָא דְיִשְׂרָאֵל תְּמוּת נַפְשִׁי מוֹתָא דְקַשִׁיטוֹהִי וּתְהֵי סוֹפִי כְּוַתְהוֹן:
@51 וַאֲמַר בָּלָק לְבִלְעָם מֶה עֲבַדְתָּא לִי לְמֵילַט סַנְאַי דְבַרְתִּיךְ וְהָא בְּרָכָא מְבָרְכַת לְהוֹן:
@52 וַאֲתֵיב וַאֲמַר הֲלָא יָת דִי יְשַׁוֵי יְיָ בְּפוּמִי יָתֵיהּ אֶטַר לְמַלָלָא:
@53 וַאֲמַר לֵיהּ בָּלָק אִיתָא כְעַן עִמִי לַאֲתַר אוֹחֲרָן דְתֶחֱזִנֵיהּ מִתַּמָן לְחוֹד קְצָתֵיהּ תֶּחֱזֵי וְכוּלֵיהּ לָא תֶחֱזֵי וּתְלוּטֵיהּ לִי מִתַּמָן:
@54 וְדַבְּרֵיהּ לַחֲקַל סְכוּתָא לְרֵישׁ רָמָתָא וּבְנָא שַׁבְעָא מַדְבְּחִין וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@55 וַאֲמַר לְבָלָק אִתְעַתֵּד הָכָא עַל עֲלָתָךְ וַאֲנָא אִתְמְטֵי עַד כָּא:
@56 וְעָרַע מֵימַר מִן קֳדָם יְיָ לְבִלְעָם וְשַׁוִי פִתְגָמָא בְּפוּמֵיהּ וַאֲמַר תּוּב לְוָת בָּלָק וּכְדֵין תְּמַלֵיל:
@57 וַאֲתָא לְוָתֵיהּ וְהוּא מְעַתַּד עַל עֲלָתֵיהּ וְרַבְרְבֵי מוֹאָב עִמֵיהּ וַאֲמַר לֵיהּ בָּלָק מָה מַלִיל יְיָ:
@58 וּנְטַל מַתְלֵיהּ וַאֲמַר קוּם בָּלָק וּשְׁמַע אָצִית לְמֵימְרִי בַּר צִפֹּר:
@59 לָא כְמִלֵי בְּנֵי אֱנָשָׁא מֵימַר אֱלָהָא בְּנֵי אֱנָשָׁא אָמְרִין וּמְכַדְבִין וְאַף לָא כְעוֹבָדֵי בְּנֵי בִּשְׂרָא דְאִינוּן גָזְרִין לְמֶעְבַּד וְתַיְבִין וּמִתְמַלְכִין דְהוּא אָמַר וְעָבֵיד וְכָל מֵימְרֵהּ מִתְקַיָם:
@60 הָא בִּרְכָן קַבֵּילִית וַאֲבָרֵכִינֵיהּ לְיִשְׂרָאֵל וְלָא אָתֵב בִּרְכְּתִי מִינֵיה:
@61 אִסְתַּכָּלִית לֵית פָּלְחֵי גִלוּלִין בִּדְבֵית יַעֲקֹב וְאַף לָא עָבְדֵי לֵיאוּת שְׁקַר בְּיִשְׂרָאֵל מֵימְרָא דַיְיָ אֱלָהָהוֹן בְּסַעְדְהוֹן וּשְׁכִינַת מַלְכְּהוֹן בֵּינֵיהוֹן:
@62 אֱלָהָא דְאַפֵּקִנוּן מִמִצְרָיִם תּוּקְפָא וְרוּמָא דִילֵיהּ:
@63 אֲרֵי לָא נַחֲשַׁיָא צָבָן דְיִיטַב לִדְבֵית יַעֲקֹב וְאַף לָא קְסָמַיָא רְעַן בִּרְבוּת בֵּית יִשְׂרָאֵל כְּעִדַן יִתְאַמַר לְיַעֲקֹב וּלְיִשְׂרָאֵל מָה עֲבַד אֱלָהָא:
@64 הָא עַמָא כְּלֵיתָא שָׁרֵי וּכְאַרְיָא יִתְנַטֵל לָא יִשְׁרֵי בְאַרְעֵיהּ עַד דְיִקְטוֹל קְטוֹל וְנִכְסֵי עֲמְמַיָא יֵירָת:
@65 וַאֲמַר בָּלָק לְבִלְעָם אַף מֵילַט לָא תְלוּטִּינוּן אַף בְּרָכָא לָא תְבָ רֵ כִ י נוּ ן:
@66 וַאֲתֵיב בִּלְעָם וַאֲמַר לְבָלָק הֲלָא מַלֵילִית עִמָךְ לְמֵימַר כֹּל דִי יְמַלֵל יְיָ יָתֵיהּ אַעֲבֵיד:
@67 וַאֲמַר בָּלָק לְבִלְעָם אִיתָא כְּעַן אֲדַבְּרִינָךְ לַאֲתַר אָחֳרָן מָאִים יְהֵי רַעֲוָא מִן קֳדָם יְיָ וּתְלוּטֵיהּ לִי מִתַּמָן:
@68 וּדְבַר בָּלָק יַת בִּלְעָם רֵישׁ רָמָתָא דְמִסְתַּכְּיָא עַל אַפֵּי בֵּית יְשִׁימוֹן:
@69 וַאֲמַר בִּלְעָם לְבָלָק בְּנֵה לִי הָכָא שַׁבְעָא מַדְבְּחִין וְאַתְקִין לִי הָכָא שַׁבְעָא תוֹרִין וְשַׁבְעָא דִכְרִין:
@70 וַעֲבַד בָּלָק כְּמָא דִי אֲמַר בִּלְעָם וְאַסֵיק תּוֹר וּדְכַר עַל כָּל מַדְבְּחָא:
@71 וַחֲזָא בִלְעָם אֲרֵי תַקִין קֳדָם יְיָ לְבָרָכָא יַת יִשְׂרָאֵל וְלָא הַלַךְ כִּזְמַן בִּזְמַן אֱלָהֵין לָקֳדָמוּת נְחָשַׁיָא וְשַׁוִי לָקָבֵיל עֶגְלָא דַעֲבָדוּ יִשְׂרָאֵל בְּמַדְבְּרָא אַפּוֹהִי:
@72 וּזְקֵף בִּלְעָם יָת עֵינוֹהִי וַחֲזָא יָת יִשְׂרָאֵל שָׁרָן לְשִׁבְטוֹהִי וּשְׁרַת עֲלוֹהִי רוּחַ נְבוּאָה מִן קֳדָם יְיָ:
@73 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@74 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וְחֵזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@75 מָה טָבָא מַשְׁכְּנָךְ יַעֲקֹב בֵּית מֵישְׁרָךְ יִשְׂרָאֵל:
@76 כְּנַחֲלִין דִמְדַבְּרִין כְּגִינַת שַׁקְיָא דְעַל פְּרָת כְּבוּסְמַיָא דִנְצִיב יְיָ כְּאַרְזִין דִנְצִבִין עַל מַיָא:
@77 יִסְגֵי מַלְכָּא דְיִתְרַבָּא מִבְּנוֹהִי וְיִשְׁלוֹט בְּעַמְמִין סַגִיאִין וְיִתְקוֹף מֵאֲגַג מַלְכֵּיהּ וְתִתְנַטֵל מַלְכוּתֵיהּ:
@78 אֱלָהָא דְאַפֵּקִינוּן מִמִצְרַיִם תּוּקְפָא וְרוּמָא דִילֵיהּ יֵיכְלוּן בְּנֵי יִשְׂרָאֵל נִכְסֵי עַמְמַיָא סַנְאֵיהוֹן וּבְבִזַת מַלְכֵּיהוֹן יִתְפַּנְקוּן וְאַרְעֲתְהוֹן יַחְסְנוּן:
@79 יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵתָא לֵית מַלְכוּ דְתִזַעֲזְעִינֵיהּ בְּרִיכָךְ יְהוֹן בְּרִיכִין וְלִיטָךְ יְהוֹן לִיטִין:
@80 וּתְקֵיף רוּגְזָא דְבָלָק בְּבִלְעָם וּשְׁקָפִינוּן לִידוֹהִי וַאֲמַר בָּלָק לְבִלְעָם לְמֵילַט סַנְאַי קְרִיתָךְ וְהָא בָּרָכָא מְבָרְכַת לְהוֹן דְנַן תְּלַת זִמְנִין:
@81 וּכְעַן אִזֵיל לָךְ לְאַתְרָךְ אֲמָרִית יְקָרָא אֲיַקְרִינָךְ וְהָא מְנָעָךְ יְיָ מִן יְקָר:
@82 וַאֲמַר בִּלְעָם לְבָלָּק הֲלָא אַף לְאִזְגַדָךְ דִי שַׁלְחַת לְוָתִי מַלֵילִית לְמֵימָר:
@83 אִם יִתֶּן לִי בָלָק מְלֵי בֵיתֵיהּ כְּסַף וּדְהַב לֵית לִי רְשׁוּ לְמֶעֱבַּר עַל גְזֵירַת מֵימְרָא דַיְיָ לְמֶעֱבַּד טַבְתָּא אוֹ בִּישְׁתָּא מֵרְעוּתִי דִי יְמַלֵל יְיָ יָתֵיהּ אֲמַלֵיל:
@84 וּכְעַן הָא אֲנָא אָזֵיל לְעַמִי אִיתָא אֲמַלְכִינָךְ מָה דְתַּעְבֵיד וַאֲחַוֵי לָךְ מָא דְיַעֲבֵד עַמָא הָדֵין לְעַמָךְ בְּסוֹף יוֹמַיָא:
@85 וּנְטַל מַתְלֵיהּ וַאֲמַר אֵימַר בִּלְעָם בְּרֵיהּ בְעוֹר וְאֵימַר גַבְרָא דְשַׁפִּיר חָזֵי:
@86 אֵימַר דִשְׁמַע מֵימַר מִן קֳדָם אֵל וִידַע מַדַע מִן קֳדָם עִילָאָה חֵיזוּ מִן קֳדָם שַׁדַי חָזֵי שְׁכִיב וּמִתְגְלֵי לֵיהּ:
@87 חֲזִיתֵיהּ וְלָא כְעַן סְכִיתֵיהּ וְלָא אִיתוֹהִי קָרִיב כַּד יְקוּם מַלְכָּא מִיַעֲקֹב וְיִתְרַבָּא מְשִׁיחָא מִיִשְׂרָאֵל וְיִקְטּוֹל רַבְרְבֵי מוֹאָב וְיִשְׁלוֹט בְּכָל בְּנֵי אֱנָשָׁא:
@88 וִיהֵי אֱדוֹם יְרוּתָּא וִיהֵי יְרוּתָּא שֵׂעִיר לְבַעֲלֵי דְבָבוֹהִי וְיִשְׂרָאֵל יַצְלַח בְּנִכְסִין:
@89 וְיֵיחוּת חָד מִדְבֵית יַעֲקֹב וְיוֹבִיד מְשֵׁיזִיב מִקִרְיַת עַמְמַיָא:
@90 וַחֲזָא יַת עֲמַלְקָאָה וּנְטַל מַתְלֵיהּ וַאַמַר רֵישׁ קְרָבַיָא דְיִשְׂרָאֵל הֲוָה עֲמַלְקָאָה וְסוֹפֵיהּ לְעָלְמָא יֵיבָד:
@91 וַחֲזָא יַת שַׁלְמָאָה וּנְטַל מַתְלֵיהּ וַאֲמַר תַּקִיף בֵּית מוֹתְבָךְ וְשַׁוֵי בִכְרַךְ תַּקִּיף מְדוֹרָךְ:
@92 אֲרֵי אִם יְהֵי לְשֵׁיצָאָה שַׁלְמָאָה עַד מָה אֲתוּרָאָה יִשְׁבִּינָךְ:
@93 וּנְטַל מַתְלֵיהּ וַאֲמַר וַי לְחַיָיבַיָא דְיֵחוֹן כַּד יַעֲבֵּד אֱלָהָא יָת אִלֵין:
@94 וְסִיעַן יִצְטַרְחַן מֵרוֹמָאֵי וִיעֲנוּן לְאָתוּר וְיִשְׁתַּעְבְּדוּן לְעֵבַר פְּרָת וְאַף אִינוּן לְעָלְמָא יֵיבְדוּן:
@95 וְקָם בִּלְעָם וַאֲזַל וְתָב לְאַתְרֵיהּ וְאַף בָּלָק אֲזַל לְאוֹרְחֵיהּ:
@96 וִיתֵיב יִשְׂרָאֵל בְּשִׁיטִין וּשְׁרֵי עַמָא לְמִטְּעֵי בָּתַר בְּנַת מוֹאָב:
@97 וּקְרָאָן לְעַמָא לְדִבְחֵי טַעֲוַתְהוֹן וַאֲכַל עַמָא וּסְגִידוּ לְטַעֲוַתְהוֹן:
@98 וְאִתְחַבַּר יִשְׂרָאֵל לְבַעֲלָא פְעוֹר וּתְקֵף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל:
@99 וַאֲמַר יְיָ לְמשֶׁה דְבַר יַת כָּל רֵישֵׁי עַמָא וְדוּן וּקְטוֹל דְחַיָב קְטוֹל קֳדָם יְיָ לָקֳבֵל שִׁמְשָׁא וִיתוּב תְּקוֹף רוּגְזָא דַיְיָ מִיִשְׂרָאֵל:
@100 וַאֲמַר משֶׁה לְדַיָנֵי יִשְׂרָאֵל קְטִילוּ גְבַר גַבְרוֹהִי דְאִתְחַבָּרוּ לְבַעֲלָא פְעוֹר:
@101 וְהָא גַבְרָא מִבְּנֵי יִשְׂרָאֵל אֲתָא וְקָרֵב לְוָת אֲחוֹהִי יָת מִדְיָנֵיתָא לְעֵינֵי משֶׁה וּלְעֵינֵי כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְאִינוּן בָּכָן בִּתְרַע מַשְׁכַּן זִמְנָא:
@102 וַחֲזָא פִּינְחָס בַּר אֶלְעָזָר בַּר אַהֲרֹן כַּהֲנָא וְקָם מִגוֹ כְנִשְׁתָּא וּנְסֵיב רוֹמְחָא בִידֵיהּ:
@103 וְעַל בָּתַר גַבְרָא בַּר יִשְׂרָאֵל לְקוּבָּתָא וּבְזַע יַת תַּרְוֵיהוֹן יַת גַבְרָא בַּר יִשְׂרָאֵל וְיַת אִתְּתָא לִמְעָהָא וְאִתְכְּלִי מוֹתָנָא מֵעַל בְּנֵי יִשְׂרָאֵל:
@104 וַהֲווֹ דְמִיתוּ בְּמוֹתָנָא עַשְׂרִין וְאַרְבְּעָה אַלְפִין: פפפ:

@1 **וירא בלק בן צפור את כל אשר עשה ישראל לאמרי.** אמר אלו שני מלכים שהיינו בטוחים עליהם לא עמדו בפניהם, אנו על אחת כמה וכמה. לפיכך ויגר מואב:
@2 **ויגר.** לשון מורא, כמו (איוב יט, כט) גורו לכם: **ויקץ מואב.** קצו בחייהם:
@3 **אל זקני מדין.** והלא מעולם היו שונאים זה את זה, שנאמר (בראשית לו, לה) המכה את מדין בשדה מואב, שבאו מדין על מואב למלחמה. אלא מיראתן של ישראל עשו שלום ביניהם. ומה ראה מואב לטול עצה ממדין, כיון שראו את ישראל נוצחים שלא כמנהג העולם, אמרו מנהיגם של אלו במדין נתגדל, נשאל מהם מה מדתו. אמרו לו אין כחו אלא בפיו. אמרו אף אנו נבא עליהם באדם שכחו בפיו: **כלחוך השור.** כל מה שהשור מלחך אין בו ברכה: **בעת ההוא.** לא היה ראוי למלכות. מנסיכי מדין היה, וכיון שמת סיחון מנוהו עליהם לצורך שעה:
@4 **פתורה.** כשלחני הזה שהכל מריצין לו מעות, כך כל המלכים מריצין לו אגרותיהם. ולפי פשוטו של מקרא כך שם המקום: **ארץ בני עמו.** של בלק. משם היה, וזה היה מתנבא ואומר לו עתיד אתה למלוך. ואם תאמר מפני מה השרה הקדוש ברוך הוא שכינתו על גוי רשע, כדי שלא יהא פתחון פה לאמות לומר אלו היו לנו נביאים חזרנו למוטב, העמיד להם נביאים והם פרצו גדר העולם, שבתחלה היו גדורים בעריות וזה נתן להם עצה להפקיר עצמן לזנות: **לקרא לו.** הקריאה שלו היתה ולהנאתו, שהיה פוסק לו ממון הרבה: **עם יצא ממצרים.** ואם תאמר מה מזיקך: **הנה כסה את עין הארץ.** סיחון ועוג שהיו שומרים אותנו עמדו עליהם והרגום: **והוא ישב ממלי.** חסר כתיב, קרובים הם להכריתני, כמו (תהלים קיח, י) כי אמילם:
@5 **נכה בו.** אני ועמי נכה לו בהם. דבר אחר לשון משנה היא (ב''מ קה ב) מנכה לו מן הדמים, לחסר מהם מעט: **כי ידעתי** וגו' **.** על ידי מלחמת סיחון שעזרתו להכות את מואב:
@6 **וקסמים בידם.** כל מיני קסמים, שלא יאמר אין כלי תשמישי עמי. דבר אחר קסם זה נטלו בידם זקני מדין, אמרו אם יבא עמנו בפעם הזאת יש בו ממש, ואם ידחנו אין בו תועלת, לפיכך כשאמר להם לינו פה הלילה, אמרו אין בו תקוה, הניחוהו והלכו להם, שנאמר וישבו שרי מואב עם בלעם, אבל זקני מדין הלכו להם:
@7 **לינו פה הלילה.** אין רוח הקדש שורה עליו אלא בלילה, וכן לכל נביאי אמות העולם, וכן לבן בחלום הלילה, שנאמר (בראשית לא, כד) ויבא אלהים אל לבן הארמי בחלם הלילה. כאדם ההולך אצל פלגשו בהחבא: **כאשר ידבר ה' אלי.** אם ימליכני ללכת עם בני אדם כמותכם אלך עמכם, שמא אין כבודו לתתי להלך אלא עם שרים גדולים מכם: **וישבו.** לשון עכבה:
@8 **מי האנשים האלה עמך.** להטעותו בא. אמר פעמים שאין הכל גלוי לפניו, אין דעתו שוה עליו, אף אני אראה עת שאוכל לקלל ולא יבין:
@9 **בלק בן צפור** וגו' **.** אף על פי שאיני חשוב בעיניך, חשוב אני בעיני המלכים:
@10 **קבה לי.** זו קשה מארה לי, שהוא נוקב ומפרש: **וגרשתיו.** מן העולם. ובלק לא אמר אלא ואגרשנו מן הארץ, איני מבקש אלא להסיעם מעלי, ובלעם היה שונאם יותר מבלק:
@11 **לא תלך עמהם.** אמר לו אם כן אקללם במקומי. אמר לו לא תאר את העם. אמר לו אם כן אברכם. אמר לו אינם צריכין לברכתך, כי ברוך הוא. משל אומרים לצרעה לא מדבשיך ולא מעקציך:
@12 **להלך עמכם.** אלא עם שרים גדולים מכם. למדנו שרוחו גבוהה ולא רצה לגלות שהוא ברשותו של מקום אלא בלשון גסות, לפיכך ויוסף עוד בלק:
@16 **כי כבד אכבדך מאד.** יותר ממה שהיית נוטל לשעבר אני נותן לך:
@17 **מלא ביתו כסף וזהב.** למדנו שנפשו רחבה ומחמד ממון אחרים. אמר, ראוי לו לתן לי כל כסף וזהב שלו, שהרי צריך לשכור חילות רבות, ספק נוצח ספק אינו נוצח, ואני ודאי נוצח: **לא אוכל לעבר.** על כרחו גלה שהוא ברשות אחרים, ונתנבא כאן שאינו יכול לבטל הברכות שנתברכו האבות מפי השכינה:
@18 **גם אתם.** פיו הכשילו, גם אתם סופכם לילך בפחי נפש כראשונים: **מה יסף.** לא ישנה דבריו מברכה לקללה הלואי שלא יוסיף לברך, כאן נתנבא שעתיד להוסיף להם ברכות על ידו:
@19 **אם לקרא לך.** אם הקריאה שלך וסבור אתה לטול עליה שכר, קום לך אתם: **ואך.** על כרחך את הדבר אשר אדבר אליך אתו תעשה, ואף על פי כן וילך בלעם, אמר שמא אפתנו ויתרצה:
@20 **ויחבש את אתנו.** מכאן שהשנאה מקלקלת את השורה, שחבש הוא בעצמו. אמר הקדוש ברוך הוא רשע כבר קדמך אברהם אביהם, שנאמר (בראשית כב, ג) וישכם אברהם בבקר ויחבש את חמורו: **עם שרי מואב.** לבו כלבם שוה:
@21 **כי הולך הוא.** ראה שהדבר רע בעיני המקום ונתאוה לילך: **לשטן לו.** מלאך של רחמים היה והיה רוצה למנעו מלחטוא, שלא יחטא ויאבד: **ושני נעריו עמו.** מכאן לאדם חשוב היוצא לדרך יוליך עמו שני אנשים לשמשו וחוזרים ומשמשים זה את זה:
@22 **ותרא האתון.** והוא לא ראה, שנתן הקדוש ברוך הוא רשות לבהמה לראות יותר מן האדם, שמתוך שיש בו דעת תטרף דעתו כשיראה מזיקין: **וחרבו שלופה בידו.** אמר רשע זה הניח כלי אמנותו, שכלי זינן של אמות העולם בחרב, והוא בא עליהם בפיו, שהוא אמנות שלהם, אף אני אתפוש את שלו ואבוא עליו באמנותו. וכן היה סופו (במדבר לא, ח) ואת בלעם בן בעור הרגו בחרב:
@23 **במשעול.** כתרגומו בשביל. וכן (מ''א כ, י) אם ישפק עפר שומרון לשעלים. עפר הנדבק בכפות הרגלים בהלוכן, וכן (ישעיה מ, יב) מי מדד בשעלו מים, ברגליו ובהלוכו: **גדר מזה וגדר מזה.** סתם גדר של אבנים הוא:
@24 **ותלחץ.** היא עצמה: **ותלחץ.** את אחרים, את רגל בלעם:
@25 **ויוסף מלאך ה' עבור.** לעבור עוד לפניו להלוך להיות לפניו במקום אחר, כמו (בראשית לג, ג) והוא עבר לפניהם. ומדרש אגדה יש בתנחומא מה ראה לעמוד בשלשה מקומות, סימני אבות הראהו:
@27 **זה שלש רגלים.** רמז לו אתה מבקש לעקור אמה החוגגת שלש רגלים בשנה:
@28 **התעללת.** כתרגומו לשון גנאי ובזיון: **לו יש חרב בידי.** גנות גדולה היה לו דבר זה בעיני השרים, זה הולך להרוג אמה שלמה בפיו, ולאתון זו צריך לכלי זין:
@29 **ההסכן הסכנתי.** כתרגומו, וכן (איוב כב, ב) הלאל יסכן גבר. ורבותינו דרשו מקרא זה בגמרא אמרו ליה, מאי טעמא לא רכבת אסוסיא. אמר להון ברטיבא שדאי ליה וכו' , כדאיתא במסכת עבודה זרה (ד, ב) :
@31 **כי ירט הדרך לנגדי.** רבותינו חכמי המשנה דרשוהו (שבת קה, א) נוטריקון יראה ראתה, נטתה, בשביל שהדרך לנגדי, כלומר לקנאתי ולהקניטני. ולפי משמעו כי חרד הדרך לנגדי לשון רטט, כי ראיתי בעל הדרך שחרד ומהר הדרך שהוא לכעסי ולהמרותי [ולהמראתי] . ומקרא קצר הוא, כמו (ש''ב יג, לט) ותכל דוד. לישנא אחרינא ירט לשון רצון, וכן (איוב טז) ועל ידי רשעים ירטני, מפייס ומנחם אותי על ידי רשעים, שאינן אלא מקניטים:
@32 **אולי נטתה.** כמו לולא, פעמים שאולי משמש בלשון לולא: **גם אתכה הרגתי.** הרי זה מקרא מסורס, והוא כמו גם הרגתי אותך, כלומר לא העכבה בלבד קראתך על ידי, כי גם ההריגה: **ואותה החייתי.** ועתה מפני שדברה והוכיחתך ולא יכלת לעמוד בתוכחתה, כמו שכתוב (פסוק ל) ויאמר לא. על כן הרגתיה, שלא יאמרו זו היא שסלקה את בלעם בתוכחתה ולא יכול להשיב, שחס המקום על כבוד הבריות, וכן (ויקרא כ, טו. טז) ואת הבהמה תהרגו, וכן (שם) והרגת את האשה ואת הבהמה:
@33 **כי לא ידעתי.** גם זה גנותו, ועל כרחו הודה, שהוא היה משתבח שיודע דעת עליון, ופיו העיד לא ידעתי: **אם רע בעיניך אשובה לי.** להתריס נגד המקום היא תשובה זו. אמר לו הוא בעצמו צוני ללכת, ואתה מלאך מבטל את דבריו, למוד הוא בכך, שאמר דבר ומלאך מחזירו, אמר לאברהם (בראשית כב, ב) קח נא את בנך וגו' , ועל ידי מלאך בטל את דברו, אף אני אם רע בעיניך צריך אני לשוב:
@34 **לך עם האנשים.** בדרך שאדם רוצה לילך בה, מוליכין אותו. **לך עם האנשים.** כי חלקך עמהם וסופך להאבד מן העולם: **ואפס.** על כרחך את הדבר אשר אדבר וגו' : **עם שרי בלק.** שמח לקללם כמותם:
@35 **וישמע בלק.** שלח שלוחים לבשרו: **אל עיר מואב.** אל מטרופולין שלו, עיר החשובה שלו, לומר ראה מה אלו מבקשים לעקור:
@36 **האמנם לא אוכל כבדך.** נתנבא שסופו לצאת מעמו בקלון:
@38 **קרית חצות.** עיר מלאה שוקים אנשים ונשים וטף בחוצותיה, לומר ראה ורחם שלא יעקרו אלו:
@39 **בקר וצאן.** דבר מועט, בקר אחד וצאן אחד בלבד:
@40 **במות בעל.** כתרגומו לרמת דחלתיה, שם עבודה זרה:
@43 **אולי יקרה ה' לקראתי.** אינו רגיל לדבר עמי ביום: **וילך שפי.** כתרגומו יחידי, לשון שופי ושקט, שאין עמו אלא שתיקה:
@44 **ויקר.** לשון עראי, לשון גנאי, לשון טמאת קרי, כלומר בקושי ובבזיון, ולא היה נגלה עליו ביום אלא בשביל להראות חבתן של ישראל: **את שבעת המזבחת.** שבעה מזבחות ערכתי אין כתיב כאן, אלא את שבעת המזבחות, אמר לפניו אבותיהם של אלו בנו לפניך שבעה מזבחות, ואני ערכתי כנגד כלן. אברהם בנה ארבעה (בראשית יב, ז) ויבן שם מזבח לה' הנראה אליו, (שם יב, ח) ויעתק משם ההרה וגו' , (שם יג, יח) ויאהל אברם וגו' ואחד בהר המוריה. ויצחק בנה אחד (שם כו, כה) ויבן שם מזבח וגו' . ויעקב בנה שתים, אחד בשכם ואחד בבית אל: **ואעל פר ואיל במזבח.** ואברהם לא העלה אלא איל אחד:
@47 **ארה לי יעקב ולכה זעמה ישראל.** בשני שמותיהם אמר לו לקללם, שמא אחד מהם אינו מבהק:
@48 **מה אקב לא קבה אל.** כשהיו ראוים להתקלל לא נתקללו, כשהזכיר אביהם את עונם, כי באפם הרגו איש. לא קלל אלא אפם, שנאמר (בראשית מט) ארור אפם. כשנכנס אביהם במרמה אצל אביו היה ראוי להתקלל, מה נאמר שם (שם כז, לג) גם ברוך יהיה. במברכים נאמר (דברים כז, יב) אלה יעמדו לברך את העם. במקללים לא נאמר ואלה יעמדו לקלל את העם, אלא על הקללה, לא רצה להזכיר עליהם שם קללה: **לא זעם ה'.** אני אין כחי אלא שאני יודע לכון השעה שהקדוש ברוך הוא כועס בה, והוא לא כעס כל הימים הללו שבאתי אליך, וזהו שנאמר (מיכה ו, ה) עמי זכר נא מה יעץ וגו' ומה ענה אתו בלעם וגו' למען דעת צדקות ה':
@49 **כי מראש צרים אראנו.** אני מסתכל בראשיתם ובתחלת שרשיהם, ואני רואה אותם מיסדים וחזקים כצורים וגבעות הללו על ידי אבות ואמהות: **הן עם לבדד ישכן.** הוא אשר זכו לו אבותיו לשכון בדד, כתרגומו: **ובגוים לא יתחשב.** כתרגומו, לא יהיו נעשין כלה עם שאר האמות, שנאמר (ירמיה ל, יא) כי אעשה כלה בכל הגוים וגו' אינן נמנין עם השאר. דבר אחר כשהן שמחין אין אמה שמחה עמהם, שנאמר (דברים לב, יב) ה' בדד ינחנו. וכשהאמות בטובה, הם אוכלין עם כל אחד ואחד ואין עולה להם מן החשבון, וזהו, ובגוים לא יתחשב:
@50 **מי מנה עפר יעקב** וגו' **.** כתרגומו, דעדקיא דבית יעקב וכו' מארבע משריתא, מארבע דגלים. דבר אחר עפר יעקב אין חשבון במצות שהם מקימין בעפר (דברים כב, י) לא תחרוש בשור ובחמור, (ויקרא יט, יט) לא תזרע כלאים, אפר פרה, ועפר סוטה וכיוצא בהם: **ומספר את רבע ישראל.** רביעותיהן, זרע היוצא מן התשמיש שלהם: **תמת נפשי מות ישרים.** שבהם:
@53 **וקבנו לי.** לשון צווי, קללהו לי:
@54 **שדה צופים.** מקום גבוה היה ששם הצופה עומד לשמור אם יבא חיל על העיר: **ראש הפסגה.** בלעם לא היה קוסם כבלק, ראה בלק שעתידה פרצה להפרץ בישראל משם ששם מת משה. כסבור ששם תחול עליהם הקללה, וזו היא הפרצה שאני רואה:
@55 **אקרה כה.** מאת הקדוש ברוך הוא: **אקרה.** לשון אתפעל:
@56 **וישם דבר בפיו.** ומה היא השימה הזאת, ומה חסר המקרא באמרו שוב אל בלק וכה תדבר, אלא כשהיה שומע שאינו נרשה לקלל, אמר מה אני חוזר אצל בלק לצערו. ונתן לו הקדוש ברוך הוא רסן וחכה בפיו כאדם הפוקס בהמה בחכה להוליכה אל אשר ירצה. אמר לו על כרחך תשוב אל בלק:
@57 **ושרי מואב אתו.** ולמעלה הוא אומר וכל שרי מואב, כיון שראו שאין בו תקוה הלכו להם מקצתם, ולא נשארו אלא מקצתם: **מה דבר ה'.** לשון צחוק הוא זה, כלומר אינך ברשותך:
@58 **קום בלק.** כיון שראהו מצחק בו, נתכון לצערו עמוד על רגליך, אינך רשאי לישב ואני שלוח אליך בשליחותו של מקום: **בנו צפר.** לשון מקרא הוא זה, כמו (תהלים קד, כ) חיתו יער, (בראשית א, כד) וחיתו ארץ, (תהלים קיד, ח) למעינו מים:
@59 **לא איש אל** וגו' **.** כבר נשבע להם להביאם ולהורישם ארץ שבעה אמות, ואתה סבור להמיתם במדבר: **ההוא אמר** וגו' **.** בלשון תמה, ותרגומו תיבין ומתמלכין, חוזרים ונמלכין לחזור בהם:
@60 **הנה ברך לקחתי.** אתה שואלני מה דבר ה', קבלתי ממנו לברך אותם: **וברך ולא אשיבנה.** הוא ברך אותם ואני לא אשיב את ברכתו: **וברך.** כמו וברך וכן הוא גזרת רי''ש, כמו (תהלים עד, יח) אויב חרף, כמו חרף, וכן (שם י, ג) ובוצע ברך, המהלל ומברך את הגוזל ואומר, אל תירא כי לא תענש, שלום יהיה לך, מרגיז הוא להקדוש ברוך הוא. ואין לומר ברך שם דבר, שאם כן היה נקוד בפתח קטן וטעמו למעלה, אבל לפי שהוא לשון פעל הוא נקוד קמץ, וטעמו למטה:
@61 **לא הביט און ביעקב** וגו' **.** כתרגומו. דבר אחר אחרי פשוטו הוא נדרש מדרש נאה. **לא הביט.** הקדוש ברוך הוא און שביעקב, כשהן עוברין על דבריו אינו מדקדק אחריהם להתבונן באוניות [באון] שלהם ובעמלן שהן עוברין על דתו: **עמל.** לשון עברה, כמו והרה עמל (תהלים ז, טו) , כי אתה עמל וכעס תביט (שם י, יד) לפי שהעברה היא עמל לפני המקום: **ה' אלהיו עמו.** אפלו מכעיסין וממרים לפניו אינו זז מתוכן: **ותרועת מלך בו.** לשון חבה ורעות כמו רעה דוד (שמואל ב' טו, לז) אוהב דוד, ויתנה למרעהו (שופטים טו, ו) וכן תרגם אנקלוס ושכינת מלכהון ביניהון:
@62 **אל מוציאם ממצרים.** אתה אמרת הנה עם יצא ממצרים, לא יצא מעצמו אלא האלהים הוציאם: **כתועפות ראם לו.** כתוקף רום וגובה שלו, וכן וכסף תועפות (איוב כב כה) , לשון מעוז המה, ואומר אני שהוא לשון ועוף יעופף (בראשית א כ) , המעופף ברום וגובה ותקף רב הוא זה ותועפות ראם עפיפת גובה. דבר אחר, **תועפות ראם.** תקף ראמים, ואמרו רבותינו אלו השדים:
@63 **כי לא נחש ביעקב.** כי ראוים הם לברכה שאין בהם מנחשים וקוסמים: **כעת יאמר ליעקב** וגו' **.** עוד עתיד להיות עת כעת הזאת אשר תגלה חבתן לעין כל שהן יושבין לפניו ולומדים תורה מפיו ומחצתן לפנים ממלאכי השרת, והם ישאלו להם מה פעל אל, וזהו שנאמר והיו עיניך רואות את מוריך (ישעיה ל, כ) . דבר אחר יאמר ליעקב אינו לשון עתיד, אלא לשון הוה, אינן צריכין למנחש וקוסם כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקדוש ברוך הוא ומה גזרותיו במרום, אינן מנחשים וקוסמים אלא נאמר להם על פי נביאיהם מה היא גזרת המקום, או אורים ותמים מגידים להם, ואונקלוס לא תרגם כן:
@64 **הן עם כלביא יקום** וגו' **.** כשהן עומדים משנתם שחרית, הן מתגברין כלביא וכארי לחטוף את המצות, ללבוש טלית לקרא את שמע ולהניח תפלין: **לא ישכב.** בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו. כיצד, קורא את שמע על מטתו ומפקיד רוחו ביד המקום, בא מחנה וגיס להזיקם, הקדוש ברוך הוא שומרם ונלחם מלחמותם ומפילם חללים. דבר אחר הן עם כלביא יקום וגו' . כתרגומו: **ודם חללים ישתה.** נתנבא שאין משה מת עד שיפיל מלכי מדין חללים ויהרג הוא עמהם, שנאמר (יהושע יג, כב) ואת בלעם בן בעור הקוסם הרגו בני ישראל בחרב אל חלליהם:
@65 **גם קב לא תקבנו.** גם ראשון מוסיף על גם השני, וגם השני על גם ראשון, וכן גם לי גם לך לא יהיה (מלכים א' ג, כו) , וכן גם בחור גם בתולה (דברים לב, כה) :
@67 **וקבותו לי.** אין זה לשון צווי, כמו וקבנו, אלא לשון עתיד, אולי יישר בעיניו ותקבנו לי משם, מלדי''רש מי''י בלע''ז [תקלל אותו] :
@68 **ראש הפעור.** קוסם היה בלק וראה שהן עתידין ללקות על ידי פעור ולא היה יודע במה, אמר שמא הקללה תחול עליהם משם, וכן כל החוזים בכוכבים רואים ואינם יודעים מה רואים:
@71 **וירא בלעם כי טוב** וגו' **.** אמר איני צריך לבדוק בהקדוש ברוך הוא כי לא יחפוץ לקללם: **ולא הלך כפעם בפעם.** כאשר עשה שתי פעמים: **לקראת נחשים.** לנחש אולי יקרה ה' לקראתו כרצונו, אמר רוצה ואינו רוצה לקללם, אזכיר עונותיהם, והקללה על הזכרת העברה תחול: **וישת אל המדבר פניו.** כתרגומו:
@72 **וישא בלעם את עיניו.** בקש להכניס בהם עין רעה, והרי יש לך שלש מדותיו עין רעה ורוח גבוהה ונפש רחבה האמורים למעלה: **שוכן לשבטיו.** ראה כל שבט ושבט שוכן לעצמו ואינן מעורבין, ראה שאין פתחיהם מכונין זה כנגד זה, שלא יציץ לתוך אהל חברו: **ותהי עליו רוח אלהים.** עלה בלבו שלא יקללם:
@73 **בנו בער.** כמו למעינו מים (תהלים קיד, ח) . ומדרש אגדה שניהם היו גדולים מאבותיהם, בלק בנו צפור, אביו בנו הוא במלכות, ובלעם גדול מאביו בנביאות, מנה בן פרס היה: **שתם העין.** עינו נקורה ומוצאת לחוץ וחור שלה נראה פתוח, ולשון משנה הוא כדי שישתום ויסתום ויגוב (ע''ז סט.) ורבותינו אמרו לפי שאמר ומספר את רבע ישראל, שהקדוש ברוך הוא יושב ומונה רביעיותיהן של ישראל מתי תבא טפה שנלד הצדיק ממנה, אמר בלבו מי שהוא קדוש ומשרתיו קדושים יסתכל בדברים הללו, ועל דבר זה נסמת עינו של בלעם. ויש מפרשים שתום העין פתוח העין, כמו שתרגם אנקלוס, ועל שאמר שתום העין, ולא אמר שתום העינים, למדנו שסומא באחת מעיניו היה:
@74 **נפל וגלוי עינים.** פשוטו כתרגומו, שאין נראה עליו אלא בלילה כשהוא שוכב. ומדרשו כשהיה נגלה עליו לא היה בו כח לעמוד על רגליו ונופל על פניו, לפי שהיה ערל ומאוס להיות נגלה עליו בקומה זקופה לפניו:
@75 **מה טבו אהליך.** על שראה פתחיהם שאינן מכונין זה מול זה: **משכנתיך.** חניותיך, כתרגומו. דבר אחר מה טבו אהליך. מה טבו אהל שילה ובית עולמים בישובן שמקריבין בהן קרבנות לכפר עליהם: **משכנתיך.** אף כשהן חרבין, לפי שהן משכון עליכם, וחרבנן כפרה על הנפשות, שנאמר כלה ה' את חמתו (איכה ד) , ובמה כלה, ויצת אש בציון:
@76 **כנחלים נטיו.** שנארכו ונמשכו לנטות למרחוק, אמרו רבותינו מברכותיו של אותו רשע אנו למדים מה היה בלבו לקללם כשאמר (פסוק א) וישת אל המדבר פניו, וכשהפך המקום את פיו ברכם מעין אותן קללות שבקש לומר כו', כדאיתא בחלק (סנהדרין קה, א) : **כאהלים.** כתרגומו, לשון מור ואהלות (תהלים מה, ט) : **נטע ה'.** בגן עדן. לשון אחר כאהלים נטע ה', כשמים המתוחין כאהל: **נטע ה'.** לשון נטיעה מצינו באהלים, שנאמר ויטע אהלי אפדנו (דניאל יא, מה) :
@77 **מדליו.** מבארותיו. ופירושו כתרגומו: **וזרעו במים רבים.** לשון הצלחה הוא זה, כזרע הזרוע על פני המים: **וירם מאגג מלכו.** מלך ראשון שלהם יכבוש את אגג מלך עמלק: **ותנשא מלכותו.** של יעקב יותר ויותר, שיבא אחריו דוד ושלמה:
@78 **אל מוציאו ממצרים.** מי גורם להם הגדלה הזאת, אל המוציאם ממצרים, בתוקף ורום שלו יאכל את הגוים שהם צריו: **ועצמותיהם.** של צרים: **יגרם.** מנחם פתר בו לשון שבירה, וכן (צפניה ג, ג) לא גרמו לבקר, וכן (יחזקאל כג, לד) את חרשיה תגרמי, ואני אומר לשון עצם הוא שמגרר הבשר בשניו מסביב והמוח שבפנים, ומעמיד העצם על ערמימותה: **וחציו ימחץ.** אנקלוס תרגם חציו של צרים, חלוקה שלהם כמו (בראשית מט, כג) בעלי חצים, מרי פלוגתא, וכן ימחץ, לשון (שופטים ה, כו) ומחצה וחלפה רקתו, שיחצו את ארצם. ויש לפתור לשון חצים ממש, חציו של הקדוש ברוך הוא ימחץ בדמם של צרים, יטבול ויצטבע בדמם, כמו (תהלים סח, כד) למען תמחץ רגלך בדם. ואינו זז מלשון מכה, כמו מחצתי, שהצבוע בדם נראה כאלו מחוץ ונגוע:
@79 **כרע שכב כארי.** כתרגומו, יתישבו בארצם בכח וגבורה:
@80 **ויספק.** הכה זו על זו:
@83 **לעבר את פי ה'.** כאן לא נאמר אלהי, כמו שנאמר בראשונה, לפי שידע שנבאש בהקדוש ברוך הוא ונטרד:
@84 **הולך לעמי.** מעתה הריני כשאר עמי, שנסתלק הקדוש ברוך הוא מעליו: **לכה איעצך.** מה לך לעשות. ומה היא העצה, אלהיהם של אלו שונא זמה הוא כו' , כדאיתא בחלק (סנהדרין קו.) תדע שבלעם השיא עצה זו להכשילם בזמה, שהרי נאמר הן הנה היו לבני ישראל בדבר בלעם (לקמן לא, טז) : **אשר יעשה העם הזה לעמך.** מקרא קצר הוא זה, איעצך להכשילם, ואומר לך מה שהן עתידין להרע למואב באחרית הימים:
@86 **וידע דעת עליון.** לכון השעה שכועס בה:
@87 **אראנו.** רואה אני שבחו של יעקב וגדלתן, אך לא עתה היא, אלא לאחר זמן: **דרך כוכב.** כתרגומו, לשון דרך קשתו (איכה ב, ד) , שהכוכב עובר כחץ, ובלע''ז דישטנ''ט [מזנק] כלומר יקום מזל: **וקם שבט.** מלך רודה ומושל: **ומחץ פאתי מואב.** זה דוד, שנאמר בו השכב אותם ארצה וימדד שני חבלים להמית וגו' (שמואל ב' ח, ב) : **וקרקר.** לשון קורה כמו אני קרתי (מלכים ב' יט, כד) מקבת בור נקרתם (ישעיה נא, א) יקרוה עורבי נחל (משלי ל, יז) פורי''יר בלע''ז [לנקב] : **כל בני שת.** כל האמות, שכלם יצאו מן שת בנו של אדם הראשון:
@88 **והיה ירשה שעיר איביו.** ישראל:
@89 **וירד מיעקב.** ועוד יהיה מושל אחר מיעקב: **והאביד שריד מעיר.** מעיר החשובה של אדום והיא רומי, ועל מלך המשיח אומר כן, שנאמר בו וירד מים עד ים (תה' עב) ולא יהיה שריד לבית עשו (עוב' א) :
@90 **וירא את עמלק.** נסתכל בפרענותו של עמלק: **ראשית גוים עמלק.** הוא קדם את כלם להלחם בישראל, וכך תרגם אנקלוס ואחריתו לאבד בידם, שנאמר תמחה את זכר עמלק (דברים כה, יט) :
@91 **וירא את הקיני.** לפי שהיה קיני תקוע אצל עמלק, כענין שנאמר ויאמר שאול אל הקיני וגו' (שמואל א' טו, ו) הזכירו אחר עמלק, נסתכל בגדלתן של בני יתרו שנאמר בהם תרעתים שמעתים שוכתים (דברי הימים א' ב, נה) : **איתן מושבך.** תמה אני מהיכן זכית לכך הלא אתה עמי היית בעצת הבה נתחכמה לו (שמות א, י) , ועתה נתישבת באיתן ומעוז של ישראל:
@92 **כי אם יהיה לבער קין** וגו' **.** אשרך שנתקעת לתוקף זה שאינך נטרד עוד מן העולם, כי אף אם אתה עתיד לגלות עם עשרת השבטים ותהיה לבער ממקום שנתישבת שם, מה בכך: **עד מה אשור תשבך.** עד היכן הוא מגלה אותך, שמא ללחלח וחבור, אין זה טרוד מן העולם, אלא טלטול ממקום למקום ותשוב עם שאר הגליות:
@93 **וישא משלו** וגו' **.** כיון שהזכיר את שבית אשור אמר, **אוי מי יחיה משמו אל.** מי יכול להחיות את עצמו משמו את אלה שלא ישים עליו הגוזר את אלה, שיעמוד סנחריב ויבלבל את כל האמות, ועוד יבואו:
@94 **וצים מיד כתים.** ויעברו כתיים שהן רומיים בבירניות גדולות על אשור: **וענו עבר.** וענו אותם שבעבר הנהר: **וגם הוא עדי אבד.** וכן פרש דניאל עד די קטילת חיותא והובד גשמה (דניאל ז, יא) : **וצים.** ספינות גדולות, כדכתיב וצי אדיר (ישעיה לג, כא) תרגומו ובורני רבתא:
@96 **בשטים.** כך שמה: **לזנות אל בנות מואב.** על ידי עצת בלעם כדאיתא בחלק:
@97 **וישתחוו לאלהיהן.** כשתקף יצרו עליו ואמר לה השמעי לי, והיא מוציאה לו דמות פעור מחיקה ואומרת לו השתחוה לזה:
@98 **פעור.** על שם שפוערין לפניו פי הטבעת ומוציאין רעי, וזו היא עבודתו: **ויחר אף ה' בישראל.** שלח בהם מגפה:
@99 **קח את כל ראשי העם.** לשפוט את העובדים לפעור: **והוקע אותם.** את העובדים: **והוקע.** היא תליה, כמו שמצינו בבני שאול והוקענום לה' (שמואל ב' כא, ו) ושם תליה מפורשת בעבודה זרה בסקילה, וכל הנסקלין נתלין: **נגד השמש.** לעין כל. ומדרש אגדה השמש מודיע את החוטאים, הענן נקפל מכנגדו והחמה זורחת עליו:
@100 **הרגו איש אנשיו.** כל אחד ואחד מדיני ישראל היה הורג שנים, ודיני ישראל שמונת רבוא ושמונת אלפים, כדאיתא בסנהדרין (יח.) :
@101 **והנה איש מבני ישראל בא.** נתקבצו שבטו של שמעון אצל זמרי שהיה נשיא שלהם, אמרו לו אנו נדונין במיתה ואתה יושב וכו' , כדאיתא באלו הן הנשרפין (סנהדרין דף פב, א) : **את המדינית.** כזבי בת צור: **לעיני משה.** אמרו לו משה, זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך וכו' , כדאיתא התם: **והמה בוכים.** נתעלמה ממנו הלכה כל הבועל ארמית קנאים פוגעים בו געו כלם בבכיה. בעגל עמד משה כנגד ששים רבוא, שנאמר (שמות לב, כ) ויטחן עד אשר דק וגו' וכאן רפו ידיו, אלא כדי שיבא פנחס ויטול את הראוי לו:
@102 **וירא פנחס.** ראה מעשה ונזכר הלכה, אמר לו למשה מקבלני ממך הבועל ארמית קנאין פוגעין בו, אמר לו קריינא דאגרתא איהו ליהוי פרוונקא, מיד ויקח רמח בידו וגו' :
@103 **אל הקבה.** אל האהל: **אל קבתה.** [אל הקבה] כמו הלחיים והקיבה כון בתוך זכרות של זמרי ונקבות שלה, וראו כלם שלא לחנם הרגם, והרבה נסים נעשו לו כו', כדאיתא התם (סנהד' פב:) :
@105 **כטל מאת ה'.** שאין בא לעולם ע"י אדם ולא יבקשו פני אדם עליו כך לא יקוה ישראל לעזרת איש כי אם בה':
@106 **כאריה בבהמות יער.** כך יהי מלכם שליט בכל: **ורמס וטרף.** רמס היא דריסת הארי כשהוא רעב ואוכלו במקומו וטרף הוא כשנושא את הטרף למעונותיו בשביל גורותיו ולבאותיו:
@108 **והכרתי סוסיך.** היא עזרת מצרים שאתם נשענים עליהם להמציאכם סוסים:
@109 **והכרתי ערי ארצך.** ולא תצטרך לערי מבצר:
@112 **והשמדתי עריך.** ואשיצי בעלי דבבך וכן ( ישעיה יד ) ומלאו פני תבל ערים וכן ( שמואל א כח ) ויהי עריך:
@114 **את ההרים.** את האבות: **הגבעות.** האמהות:
@116 **מה עשיתי לך.** תן לבך להכיר מה טוב עשיתי לך: **ומה הלאתיך.** בעבודתי: **ענה בי.** העד בי:
@117 **כי העליתיך.** אע"פ שעשיתי לך כל הטובה הזאת לא הלאתיך בעבודה גדולה ובקרבנות גדולים: **את משה אהרן ומרים.** ת"י משה לאלפא מסורת דינין ואהרן לכפרא על עמא ומרים לאוראה לנשיא:
@118 **ומה ענה אותו בלעם בן בעור.** מה אזעום לא זעם ה' ( במדבר כג ) שלא כעסתי כל אותן הימים: **מן השטים.** שחטאתם לי שם דעו צדקותי שלא מנעתי טובתי ועזרתי מכם עד הבאתי אתכם לגלגל וכבשתי לפניכם שם את הארץ:
@119 **אכף.** אהיה כפוף:
@120 **נחלי שמן.** למנחות: **האתן בכורי.** קרבן לפשעי:
@121 **הגיד.** הקב"ה לך אדם מה טוב לך לעשות: **והצנע לכת.** ת"י הוי צנוע למיהך בדחלא דאלהך, ד"א והצנע לכת לא כמדת הקב"ה מדת בשר ודם מדת בשר ודם אדם מבייש את חבירו ובא לפייסו ואומר לו איני מתרצה לך עד שיבא פלוני ופלוני שבזיתני לפניהם אבל הקב"ה אין חפץ אלא שישוב אליו בינו לבין עצמו:

@2 **ויקץ מואב מפני בני ישראל.** ר"ל שהיה במצוקה גדולה וביראה פן ישחיתוהו ישראל כמו שהשחיתו את האמורי:
@3 **כלחוך השור את ירק השדה.** אמ' זה לפי שהשור הוא רב המזון וכאש' יבא אל עשב השד' יכלנו ויאכלנו בשלמות מזולת שישאיר בו דבר והוצרך להזכיר שבלק בן צפור היה מלך למואב בעת ההיא בעבור מה שרצה להזכיר מדברי בלעם ובלק:
@4 **והנה כסה את עין הארץ.** ר"ל כי לרבוים יכסו את מראה הארץ שלא יוכל איש לראות את הארץ כי היא כלה מכוסה בהם:
@4 **והוא יושב ממולי.** אמר זה לפי שהם היו אז בערבות מואב ושם חנו אצל הירדן מבית הישימות עד אבל השטים כמו שנזכר בפרשת ואלה מסעי:
@5 **לכה נא ארה לי את העם הזה וגו'.** אחשוב כי מפני שהיה בלעם קוסם כאמרו זאת בלעם בן בעור הקוסם הרגו לפי חרב ולזאת הסבה גם כן הביאו לו קסמים הנה היה יודע בקסם העתיד לבא על איש ואיש ביותר שלם שאפשר שתגיע זאת הידיעה לקוסם ולזה נתיחד בזה העניין מבין שאר הקוסמים שבדברים רבים מדבריו נתקיימו ומצד תחבולותיו כאשר היה יודע מצד הקסם שיגיע רע לאיש מה היה מקלל אותו וכאשר היה יודע העת הראוי שיגיע בו לאיש מהטוב היה מברך אותו והיה מביא זה האנשים להאמין כי מבורכיו הם מבורכים ומקולליו הם מקוללים ואפשר עוד שהיה עושה מעשים ממין הנחש והכשוף להזיק למי שירצה ולהועיל למי שירצה כמו שנבאר עם זכירתנו תועלות זאת הפרשה:
@6 **וקסמים בידם.** הם כלים מה יעורר בהם הקוסם כח הדמיון להגיע אליו הקסם וראוי שתדע כי אלו הדברים הנזכרים מזאת הפרשה מבלעים הם נבואות לא קסמים וזה יתבאר במה שבארנו מסגולות הקסם והנבואה ומה שיוכר בו אחד אחד מהם בב' מספר מ"י ואחשוב כי ה' ית' השיבו נביא בזה הזמן בעבור עוצם השגחתו על ישראל כי היה ראוי שתשמרהו זאת המעלה מנתינת העצה להכשיל ישראל בדברים מגונים כמו הזמה וע"ז ועם כל זה לא נשמר מזה כי הוא נתן עצה למואבים להפקיר בנותיהם לזנות עם ישר' כדי שיפתו אותם לעבוד ע"ז כמו שנתבאר בפרשת ראשי המטות אמר הן הנה היו לבני ישראל למסור מעל ביי' על דבר פעור:
@8 **מי האנשים האלה עמך.** אל על פי שהש' ית' יודע הכל הנה יבואו ממנו השאלות לדבר כלשון בני אדם ולהישיר השופטים שנתיישבו בידיעת אמתת הדבר קודם שישפטו בו:
@12 **כי מאן יי' לתתי להלוך עמכם.** לפי שהיה רצון בלעם ללכת שם לא רצה להגיד למלאכי בלק מה שאמר השם ית' לו לא תאור את העם כי ברוך הוא כי חשב שאם היה בלק יודע זה לא היה מוסיף לשלוח לו אך אמר להם כי מאן יי' לתתי להלוך עמכם כאלו אמר כי לא היה רצון ה' למנוע ממנו ההליכה שם אבל מנע ממנו ההליכה עמהם והנה היה חושב בלעם כי אולי בעת אחר יאות השם יתע' להניחו ללכת שם לקוב את העם ולפי שהרגיש בלק בזה רוצני שזה המאמר לא היה מחייב שלא יתרצה ללכת לבלק אבל היה מחייב שלא יתרצה ללכת עם אלו ששלח לו ראשונה חשב כי אולי היה זה לבקשת הכבוד ולזה הוסיף בלק לשלוח שרים רבים במספר ויותר נכבדים מהראשונים ושלח לו בביאור כי כבד יכבדהו מאד כדי שיתרצה עכ"פ לבא ליקוב את העם:
@17 **מלא ביתו.** הרצון בו בית מלא כמו שפירש החכם אבן עזרא כי לא יהיה תועלת לבלעם אם יתן לו בלק פעל מלא הבית כסף וזהב:
@18 **שבו נא בזה גם אתם הלילה.** אמר זה לבאר להם כי לא אמר מה שאמר לשרים הראשונים לבקשה הכבוד כמו שחשב בלק אך אמר זה לפי שאינו יכול לעשות דבר אם לא ימלך בשכינה ואשר יאמר לו השם ית' יעשה ולזה אמר יצטרך לכם גם כן להתעכב פה הלילה כי אז בעת השינה יותר נכון לקבל כח עליון כמו שבארנו בב' מספר מ"י ואז יודיעני ה' מה אעשה:
@19 **אם לקרא לך באו האנשים קום לך אתם.** ר"ל אם הם רוצים לקרא לך שתבא אצל בלק קום לך אתם אך לא תלך שם לקוב את העם כמו ששאל בלק אך את הדבר אשר אדבר אליך אותו תעשה ואמנם אמר לו כך כי תחלה אמר השם ית' לא תלך עמהם לא תאור את העם כי ברוך הוא וחשב בלעם מזה המאמר שהשם ית' מנע ממנו ההליכה עמהם אע"פ שלא יאור את העם ולזה אמר אל שרי מואב כי מאן יי' לתי להלוך עמכם ולזה אמ' לו עתה שאינו מונע ממנו ההליכה אל בלק אך מונע ממנו מה ששאל ממנו לקוב את העם:
@20 **ויקם בלעם בבקר ויחבוש את אתונו.** יש בזה הספור שאלות קשו' מאד הא' איך יתכן שתראה האתון את מלאך יי' והנה לא יראהו מי שאינו נביא כמו שנתבאר שם בסוף דניאל והאנשים אשר היו עמו לא ראו את המראה אבל חרדה גדולה נפלה עליהם ולא תטעה בענין המלאך שנראה למנוח ולאשתו כי הוא היה איש נביא כמו שביארנו שם ואם אמרנו שהש"י עשה זה על דרך המופת הנה ישאל שואל איזה תועלת היה בזה המופת והנה לא היה המכוון מזה אלא שיאמר המלאך לבלעם כי הוא יצא לשטן לו אם תהיה כונתו לקוב את העם ובהיות הענין כן למה לא נראה לו המלאך ראשונה וחרבו שלופה בידו ויגיע מזה התכלית המכוון מהשם ית' בזה ולא נצטרך לחדוש זה המופת הנפלא ר"ל שתראה האתון אל מלאך יי'. ואם אמרנו שזה המלאך היה נביא הנה יפול הספק עדיין לאי זה תועלת הוצרך להתחדש אז על דרך המופת שתדבר האתון עם שלא יוכל לומר מי היה זה הנביא ועוד איך לא ראוהו שרי בלק ולא נערי בלעם כי לא נזכר פה שראוהו אחר זולתי האתון ובלעם אחריה. והוא מבואר שהשם יתעלה לא יחדש המופתים ללא צורך אמר שלמה האלהים עשה שייראו מלפניו והנה דעת רבותינו ז"ל הוא שזה הענין היה כפשוטו ולזה אמרו שפי האתון היה מהדברים שנבראו בין השמשות והנראה בעינינו לפי השרשים האמתיים הנראים מדברי הנביאים ומהעיון שזה הספור היה עניין שקרה לבלעם במראה הנבואה כמו העניין בספור לקיחת הושע גומר בל דבלים ושאר מה שנמשך בספור ההוא אשר הוא בהכרח דבר נראה לו במראה הנבואה לא דבר שקרה והנה נדמה לבלעם בחלומו של נבואה שכבר יה לילה כשבאהו דבר ה' ית' במה שאמר לו אם לקרא לך באו האנשים קום לך אתם ואחר זה נדמה לו בחלומו שהיה בקר ושהוא קם וחשב את אתונו והלך עם שרי מואב כי כן היה הסכמתו אם היה מקיץ לפי שאן מראין לו לאדם אלא מהרהורי לבו ולזה תמצא כי תכונת האדם בחלומו הם מתיחסות לתכונותיו בהקיץ והנה סבב השם יתעלה שיקרה לו בהליכתו מה שהורה לו שלא הסכימו מן השמים שילך שם לתכלית אשר הוא פונה אליו כי היה דעתו עכ"פ להשתדל להזיק לישראל לפי היכולת ולזה ספר שקרה לו זה המקרה כי האתון נטתה מן הדרך והלכה בשדה וכאשר הכה בלעם אותה להטותה הדרך נלחצה אל הקיר ולחצה רגל בלעם אל הקיר ושב להכותה ואחר זה רבצה תחתיו ושב להכותה ונדמה לו בחלומו כאלו פתח השם יתעלה פי האתון ודברה עמו שתי פעמים והוא השיב לה כדבר איש לאיש אחר ואחד נראה לו המלאך ונתבאר לו מדברי המלאך בחלומו שנטיית האתון מן הדרך היתה מפני ראותה מלאך יי' והנה אמר אם רע בעיניך אשובה לי לפי שהיה דומה לו שכבר החזיק בדרך ובא לו הצווי שנית שילך עם האנשים אך לא ידבר רק מה שידבר אליו השם יתעלה וזה כולו היה מהשגחת השם יתע' על ישראל כמו שזכרנו כי זה היה הראוי שיוסיף אימה לבלעם מעבור את פי השם יתע' בהשתדלותו לגרום נזק לישראל והנה מה שאמר אחר זה וילך בלעם עם שרי בלק הוא ענין שהיה בהקיץ ולזה הוצרך להגיד זה כי הראשון היה במראה הנבואה ולולי זה הפירוש לא היה צריך לומר שנית ולך עם שרי מואב:
@21 **ויחר אף יי' כי הולך.** הוא רוצה לומר לפי מה שנתבאר להשם ית' שהוא היה הולך לא לתכלית שיזהר מה שהזהירו השם יתעלה חרה אפו עליו ורצה להראותו דבר מפחד ימנע בעבורו מהשתדל להזיק לישראל:
@21 **לשטן לו.** הוא מענין שטה מעליו ועבור והרצון בו למנעו ממה שהיה מכוין אליו ולהטותו ממנו:
@21 **ושני נעריו עמו.** לפי שממנהגו היה כשהיה הולך היה מוליך עמו שני נעריו נדמה לו כך:
@23 **במשעול הכרמים.** הוא השביל שבין הכרמי' והיו הכרמים ההם מוקפים גדר:
@28 **כי התעללת בי.** ר"ל שעשית כנגדי פעולות קשות כטעם את שר התעללתי במצרים:
@29 **ההסכן הסכנתי.** ההרגל הרגלתי:
@31 **כי ירט הדרך לנגדי.** ר"ל נטה ונתעות הדרך כי אתה רוצה להחטיא כונתי ולנטות מן הדרך אשר צויתי לך:
@32 **אולי נטתה מפני וגומ'.** ר"ל לולא שנטתה מפני כשהייתי מוצא אותך תכף מרוב חרון אפי על הסכמתך זאת הייתי חורג אותך לבדך לא היא כי היא אינה חוטאת בזה והנה בנטותה מפני הצילה אותך מהמות כי שקטה חמתי בין הזמן הזה ואתה הכית אותה על זה שלש פעמים בהצילה אותך הנה בודאי לא היה זה מן הראוי והנה אמר גם אותכה הרגתי כי הוא היה מתרעם על מה שהתעללה בו האתון וכאלו אמר לא הספיק לך מה שהתעללה בך האתון כי יותר קשה ממנו הייתי עושה לך ואמר ואותה החייתי לפי שהיה מפורסם שלא יראה אחד מלאך יי' ויחי'. אמר יעקב אבינו כאשר ראה פנואל כי ראיתי אלהי' פנים אל פנים ותנצל נפשי. ואמ' מנוח מות נמות כי אלהי' ראינו וכאלו אמר שלא די שלא הרגתי אותה אבל הצלתיה מהמות הראוי לה מפני ראותה אותי:
@35 **ויצא בלק לקראתו אל עיר מואב.** הנה יצא עד קצה גבול ארצו לקראת בלעם לכבדו כי כן שלח לו כי כבד אכבדך מאד ולכבודו גם כן זבח בלק בקר וצאן ושלח לבלעם ולשרים אשר אתו:
@40 **ויעלהו במות בעל וירא משם קצה העם.** יש לשאול בכאן שאלה עמוקה והוא שכבר יראה מזה המקום ומה שאמר אחר זה אפס קצהו תראה וכלו לא תראה ומה שאמר וישא בלעם את עיניו וירא את ישראל שוכן לשבטיו שכבר היה מדקדק בלעם שיראה את ישראל כדי שיהיה זה כלי לקוב את ישראל. והנה יפול בזה ספק חזק אי זה רושם היה בראותו ישראל להגיע להם קללה ועונש ואם אמרנו כי אולי בעין הרע היה מגיע היזק למי שיביט בהם מצד איד ארסיי נתך ממנו הנה ידמה כי ממקום רחוק כל כך לא היה אפשר שיגיע הפעלות למובטים מבני האיד הנתך מעין בלעם כי הוא לא יפעל באי זה מרחק הזדמן ועוד איך לא היו נזוקים העומדים לפניו ועוד איזה רושם היה בזה אל שיהיו מבורכים אשר יברכם והנה מצאנו שאמר לו בלק גם קוב לא תקבנו גם ברוך לא תברכנו והנראה בעיני שהוא היה רוצה לראותם כדי שתתבודד מחשבתו בהם ויהיה זה סבה אל שיודע לו מה שראוי שיקרה לחלק חלק מהם מרע או מטוב כי זה מתנאי הנבואה והקסם כמו שבארנו בב' מספר מ"י והנה היה במות בעל מקום גבוה אצל גבול מואב היה יכול בלעם לראות משם קצה העם. ואמר החכם אבן עזרא כי הוא בעל במות ארנון ונכון הוא:
@41 **בנה לי בזה ז' מזבחות והכל לי בזה שבעה פרים ושבעה אילים.** כבר ביארנו בפרשת נח כי העלאת העולה מישרת להגעת הנבואה וכ"ש כאשר נכפל עניינה זה ההכפל הנפלא והנה ספר שבלעם ובלק העלו עולות אך כשהעלו אותן אמר בלעם לבלק שיתיצב על עולתו לשמרה לכבוד השם יתעלה והוא יראה אם תקרה לו נבואה מצד זאת ההישרה שהישיר עצמו אליה:
@43 **וילך שפי.** רוצה לומר שהלך אל מקום גבוה לראות משם ישראל:
@44 **את שבעה המזבחות ערכתי.** ידמה שצוהו השם יתעלה לעשות כן קודם זה כדי להמשיך אליו הנבואה ולזה אמר את שבעת המזבחות ערכתי ולא אמר שבעת מזבחות ערכתי:
@47 **מהררי קדם.** רוצה לומר מהרים מזרחיים:
@47 **לכה ארה לי יעקב.** רוצה לומר ששלח לו שיקלל יעקב והרצון בו בני ישראל כי כבר נקראו יעקב כמו שנקראו ישראל:
@47 **ולכה זועמה ישראל.** רוצה לומר הביא הזעם והקללה על ישראל:
@48 **מה אקוב.** הנה השם יתעלה לא קללהו ומה מועיל קללתי אותו:
@49 **כי מראש צורים אראנו וגומ'.** אמר זה לפי שהוא היה רואה אותם למקום גבוה מאד כמו שאמר וילך שפי והרצון בו כאשר אראנו מראש צורים ומגבעות רמות הנה מצאתי שזה העם ישכון לבדד להיות נבדל משאר האומות וקדוש מהם ולזה לא יתחשב בגוים שיהיה נמנה עם שאר הגוים והיה זה כן כי ההמנות ישיג הדברים מצד מה שהם מסכימים והמשל שלא ימנה המונה סוס והשחרות שנים ולא הסוס והחמור מהצד שהם בו בלתי מסכימים אבל ימנה הסוס והסוס וימנה הסוס והחמור מצד מה שהם בעלי חיים שהם מסכימין בו והמשל שאם ישאל אדם כמה בעלי חיים שם והיה שם סוס וחמור יאמר שנים והנה אמר זה על צד ההפלגה להורות שאין יחס בין ישראל ובין שאר האומות:
@50 **מי מנה עפר יעקב.** ר"ל כי למעלתם והצלחתם ירבו מאד כעפר כאמרו והיה זרעך כעפר הארץ ולזה לא יוכל למנות אותם וגם לא יוכל לספור מספר רובע ישראל. ר"ל הדגל שלכל רוח שהיה בו ג' שבטים:
@50 **תמות נפשי מות ישרים ותהי אחריתי כמוהו.** אמר מורה על טוב הצלחת ישראל לקנות החיים הנצחיים מצד מה שהישירה אותם התורה אל זה מי יתן שתמות נפשי מות ישרים בישראל ותהי אחריתי כמוהו אחרית ישראל לקנות העולם הבא:
@57 **ויאמר לו בלק מה דבר יי'.** אמר לו זה לפי שכבר אמר לו בלעם כי אשר ישים יי' בפי אותו אשמור לדבר:
@58 **קום בלק ושמע.** ר"ל קום ממקומך ובא אלי לשמוע דברי וכן הרצון באמרו האזינה עדי שיתקרב אליו להאזין קולו:
@59 **לא איש אל ויכזב.** הרצון בו למה תחשוב שיסכים עתה השם יתעלה לקללם וכבר גלה דעתו קודם זה שאין רצונו לקללם כאמרו מה אקוב לא קבה אל הנה השם יתעלה אינו במדרגה שיכזב בדבריו כי אין אצלו כי אם אמת ואינו מתחרט גם כן ממה שגמר בלבו לעשותו כי אינו בן אדם שיתנחם האם הוא יתע' אמר לעשות דבר ולא יעשהו או דבר דבר ולא יקימנו.
@60 הנה לקחתי מהשם יתעלה לברך אותם והנה ברך אותם השם יתעלה ולא אשוב אחור הברכה ההיא כי לא אוכל:
@61 **לא הביט און ביעקב ולא ראה עמל בישראל.** ר"ל כאשר לא הביט השם יתעלה עול ועמל בישראל והוא בלכתם בדרכי התורה אז השם אלהיו עמו להשגיח בו ולהפיל לפניו אויביו בתרועה חזקה ומקרים מרעידים והנה זה האלוה שהו' עמם הוא האל המוציא אותם מארץ מצרים באותות ובמופתים לא באמצעות מערכת הכוכבים אך בגבורה חזקה והמשילה לתוקף הראם לדבר כלשון בני אדם והנה העיר בזה על שהצלחות ישראל הם למעלה מהצלחות שאר האומות בי בכל עת שילכו בדרכי השם יתעלה בדרך שלא יראה בהם און ועמל הם מושגחים ממנו בצד שלא תועיל לאויביהם ההצלחה שתהיה להם מפאת הכוכבים כי האל המשגיח בם הוא שליט על הכל ועושה כרצונו מהכל וזה גם כן ממה שימנע מהקוסם ידיעת מה שיתכן שיקרה לישראל מטוב או רע וזה כי הקוסם יעמוד על זה מצד שפע הכוכבים כמו שבארנו בספר מלחמות השם וישראל אינם תחת ממשלת הככבים בעת שהם טובים ולזה אמר כי לא נחש ביעקב ולא קסם בישראל רוצה לומר שאין כח בנחש ובקסם לעמוד על אמתת מה שיתחדש להם לסבה שזכרנו ולזאת הסבה הנה כאשר יאמר ליעקב ולישר' מה פעל אל ר"ל מה גזר לפעול במה שעתיד לא יבאו לידיעת זה מצד הנחש והקסם אבל יודע להם זה מצד הנבואה:
@64 **הן עם כלביא יקום וכארי יתנשא.** ר"ל מצד עוצם השגחת השם יתעלה בהם יקומו בגבורה נפלאה לכלו' אויביהם במהירות כמו הלביא והאריה שלגבורתם יטרפו תמיד ובזריזות גדול כן זה העם לא ישכב עד יאכל טרף ודם חללים ישתה כי השם יתעלה המשגיח בם לא תקצר ידו מעשות כל אשר חפץ והנה בזה המאמר הישיר בלעם את בלק לדעת מאי זה מקום יבא הטוב לישראל ובסבת אי זה דבר ר"ל שזה יהיה להם כשישמרו מחטא ליי' בדרך שלא יראה בהם און ועמל ומזה המקום נתישר בלק לקחת עצה להחטיא ישראל או אפשר שבלעם נתן לו בביאור העצה ההיא ר"ל להפקיר בנות מואב לישראל כדי שיסיתום לטעות אחר ע"ז:
@67 **אולי יישר בעיני האלהים וקבותו לי משם.** ראוי לספק בזה איך אמר זה בלק לבלעם וכבר אמר לו בלעם לא איש אל ויכזב ובן אדם ויתנחם ואיך השיב לו בלעם בנה לי בזה שבעה מזבחו' והנה היה ראוי שישיב לו כי לשוא הוא טור בזה כי אין השם יתע' בן אדם ויתנחם. אלא שהיתר זה הספק אינו ממה שיקשה כי אולי חטאו ישראל אחר זה ויישר בעיני השם יתעלה עם שהוא אפשר ששער בלק על צד הקסם כי מהמקום ההוא נכון לבא רע על ישראל והסכים לו בלעם בזה ואם לא נזכר.
@71 ולפי שכבר ראה בלעם כי טוב בעיני ה' לברך את ישראל לפי שהשגחתו דבקה בהם הנה הלך כפעם בפעם לקראת נחשים ר"ל להשתדל לדעת על צד הנחש מה שיתכן שיקרה לישראל כי אין כח בנחש להודיע זה כמו שהקדים ואמר כי לא נחש ביעקב אך יהיה כח בנחש ובקסם להודיע זה בעת סור ההשגחה מהם ולפי שראה בלעם שהשגחת השם יתעלה דבקה בהם עזב עניין הנחשים ושת אל המדבר פניו לראות ישראל כדי שיעמוד בנבואה על מה שיתכן שיקרה להם מטוב או רע:
@73 **שתום העין.** ר"ל פתוח העין:
@74 **נופל גלוי עינים.** זאת ראיה שאף על פי שהיתה הנבואה מגעת לו בהקיץ היה נופל מרוב ההתבודדות ולא היה בו כח לעמוד על רגליו:
@76 **כנחלים נטיו.** ר"ל נמשכו ממקורותיהם המשך רב עד שנטו במקומות רבים שכל מה שירוצו מימיהם יעמדו אחריהם תחתיהם והוא מעניין נוטה שמים כיריעה:
@76 **כאהלים נטע יי'.** מצאנו נטיעה באהלים כאמרו ויטע אהלי אפדנו והנה רמז בזה אל השמים כאמרו וימתחם כאהל לשב:
@77 **יזל מים מדליו.** אמר זה על צד הפלא וההפלגה לפי שהדולה ממים נובעים הנה המים שבדלי אינם נובעים ולזה יכלו מהדלי ולזה אמר שגם מדליו יזלו מים והרצון בו שבכל אחד מהם תמצא הברכה עד שזרעו יהיה תמיד במים רבים להפרות ולהרבות או יהיה הרצון באמרו מדליו מדליותיו. ר"ל מסעפים וזה יהיה מרוב המים אשר הוא גדל בהם ועצמותיהם יגרם יפרק וישבר העצמות והנה הגרם הוא עצם כאמרו גרמיו במטיל ברזל:
@78 **חציו ימחץ.** ר"ל שכל אחד מחצי השם יתעלה ימחץ אויבי ישראל:
@81 **ברח לך אל מקומך.** לך לך במהירות אל מקומך:
@84 **לכה איעצך אשר יעשה והעם זזה לעמך באחרית הימים.** הנה קרא הודעת העתידות עצה לפי שהתועלת בזאת ההודעה הוא הישרה ללקיחת עצה כדברים טרם בואם וכן הכונה במה שאמר עצות מרחוק. ונדיב נדיבות יעץ. פלא יועץ. כמו שפירשנו בספר ישעיה או יהיה חסר ותהיה הכונה בו איעצך מה תעשה ואודיעך את אשר יעשה העם הזה לעמך באחרית הימים והנה הביאור הראשון הוא היותר נכון לפי מה שאחשוב:
@87 **אראנו ולא עתה.** ר"ל שאחר זמן רב יהיה זה לפי מה שזכר תחלה ממואב לא היה כי אם אחר זה כמו ארבע מאות שנה כי כשנבנה הבית היו ארבע מאות ושמונים שנה מעת צאת בני ישראל מארץ מצרים:
@87 **אשורנו ולא קרוב.** כפל הענין במלות שונות או הוא שב למה שזכר מלך המשיח שיהיה אחר כן זמן ארוך אורך נפלא והוא היותר נכון ולזה שנה לשונו ממה שאמר תחלה ולא עתה כי כבר יצדק על מה שיהיה אחר זמן קרוב שהוא לא עתה ולא יצדק עליו שהוא לא קרוב ולזה הורה אמרו ולא קרוב על מרחק יותר עצום:
@87 **דרך כוכב.** רמז למלך המשיח שיגלו ויראו פעולותיו בקצות הארץ ולזה המשילו לכוכב שהוא נגלה ונראה לכל להורות גם כן על עליונותיו ורוממותו ועוד שכמו שמהכוכב יושפעו פעולות רבות בזה העולם מזולת שיפגש במתפעלים ממנו כן יושפעו מהמשיח פעולות רבות בזולת פגישה כאמרו והכה ארץ בשבט פיו וברוח שפתיו ימית רשע. ולזה אמר דרך להתפשט פעולותיו בקצה הארץ:
@87 **וקם שבט מישראל.** רמז לדוד והנה קראו שבט שיכה בפגישה וכן העניין במלחמת דוד ואמר עליו וקם להורות שפעלותיו במלחמותיו לא יתפשטו בקצות הארץ אבל יעמוד במקומו וילחם בסביבותיו ולפי שאמר לו שיודיעהו מה יעשה העם הזה לעמו באחרית הימים הקדים לזכור תחלה מלחמת דוד על מואב שמדרם בחבל שני חבלים להמית וחבל אחד להיות וידמה שהחבל שהיה להחיות היה באמצע ולזה אמר שהוא הכה פאות מואב ואחר זה זכר במלחמת המשיח על כל הגוים כי הם בני שת כי לו לבדו נתקיים המציאות ונח היה מזרעו.
@87 וטעם **וקרקר כל בני שת** שיהרוס אותם וירמסם כטעם מקרקר קיר:
@88 **והיה אדום ירשה.** ר"ל ע"י דוד כי הוא הכרית כל זכר באדום:
@88 **והיה ירשה שעיר אויביו.** ר"ל אויביו. ר"ל אויבי ישראל והוא אדום שזכר תחלה כי הר שעיר היה לבני אדום כמו שנזכר בפרשת ואלה הדברים:
@88 **וישראל עושה חיל.** רוצה לומר כי בימי דוד ינצחו ישראל כל מי שילחם עמו כמו שנתבאר זה בספר שמואל:
@89 **וירד מיעקב והאביד שריד מעיר.** רוצה לומר מכל עיר מארץ אדום וכן היה בימי דוד שנאמר כי ששה חדשים ישב שם יואב עד הכרית כל זכר באדום והיה אמרו וירד מיעקב רמז לדוד ואפשר עוד שיהיה הרצון באמרו ישראל עושה חיל כי קודם המשח דוד היה ישראל עושה חיל על ידי שאול כאומרו ויעש חיל ויצל את ישראל מיד סוסיהו אך כאשר ימשול דוד הוא יכלה זאת האומ' באופן שיאביד שריד מכל עיר ממנה:
@90 **וירא את עמלק ראשית גוים עמלק.** ר"ל שהוא הראשון שנלחם בישראל:
@90 **ואחריתו עדי אובד.** ע"י שאול:
@91 **וירא את הקני.** הוא היה ממשפחת יתרו והנה היה מושבו סמוך לישראל כמו שנתבאר בספר שופטים ובין ישראל היה יושב והגלהו מלך אשור ונהג אותו בשבי ולאורך ימי שביו אמר זה המאמר הנה מושביך הזק וקנך שמת בסלע שהוא מקום תקיף וכל זה לא יצילך כי יהיה לכליון קין ועד מה אשור תשבך מחנה אשור הנה מאורך השבי ידמה שיהיה התכלית היות קין לכליון או ירצה בזה אם יהיה קין לכליון יותר טוב להם מהיות בזה השבי כל זה הזמן הארוך:
@93 **וישא משלו ויאמר איו מי יחיה משומו.** אלה הדברים על לבו ממלך אשור כי הוא יעשה רעות רבות לגוים רבים:
@94 **וצים מיד כתים.** ידוע כי כתים היו מבני יון כי כן כתוב ובני יון אלישה ותרשיש כתים ודודנים ואמר שממקום כתים יצאו אנשים דומים לחיות מדבריות מצד רוב אכזריותם והם יענו אשור. ויענו העברים אשר שבה מלך אשור:
@94 **וגם הוא עדי אובד.** כמו עמלק ר"ל אשור כי בו היו דבריו:
@96 **וישב ישראל בשטים.** שם היה מושבם כי הוא היה בערבות מואב כו שזכרנו והתחילו תחלה להתפרץ בעריות ומשם נתפתו לאכל בזבח ע"ז והשתחוו לאלהי מואב:
@98 **ויצמד ישראל לבעל פעור.** רוצה לומר נתחבר לעובדי בעל פעור כטעם אמרו ובעל בת אל נכר:
@99 **והוקע אותם ליי' נגד השמש.** הוא בענין אמרו והוקענום ליי' והרצן בזה קח את כל ראשי העם והם השופטים שהיו שרי אלפים ושרי מאות שרי חמשים ושרי עשרות שיעשו אלו המשפטים מהעובדים והוקע את החוטאים ליי' לעיני הקהל כדי שיוסרו השאר וזכר ההוקעה הוא ההריגה והמתה אם בתלייה אם בזולת זה:
@100 **הרגו איש אנשיו הנצמדים לבעל פעור.** ר"ל העוברים אשר תח הנהגתו:
@101 **הנה איש מבני ישראל בא.** הוא היה נשיא שבט שמעון כמו שזכר:
@101 **ויקרב אל אחיו המדינית.** ר"ל שהביאה במחנה ישראל בפרהסיא שהיו רואים זה משה וכל העדה והביאה לאהלו לשכב עמה והיה עושה זה בעת שהיו ישר' מתים במגפת והיו מומתים על ידי השופטים ולזה היו בוכים פתח אהל מועד ונכון הוא מה שאמרו ז"ל שומרי היה מריב עם משה בעובר שלקח בת יתרו והוא מצוה עתה להרוג הנזקק לבת אל נכר ולזה הביא אותה לעיני מש במחנה ישראל:
@102 **וירא פינחס בן אלעזר.** למדנו מזה שהבועל ארמית קנאין פוגעים בו אך בתנאי שיעשה זה בשעת מעשה כמו שמצינו בפנחס שדיקר את שניהם בשעת מעשה באופן שהיה עדות שהוא היה שוכב עמה אז ולזה ספר שבדקרו את איש ישראל דקר עמו האשה בדרך שנכנס הרומח במעיה והנה בזה הפועל נעצרה המגפה מעל בני ישראל וידמה שהמתים בזאת המגפה היו כלם משבט שמעון כי תמצא במספרם בפרשת פינחס שהוא יותר חסר מאד ממה שהיה בפרשת במדב' סיני מאי זה שיהיה משאר השבטים ולזה הסכימו רבותינו ז"ל כי אלו היו כלם משבטו של שמעון. ובכאן נשלם הביאור בזאת הפרשה.

@71 **וירא בלק בן צפור את כל עד סוף הפרשה.**
@71 **ביאור דברי זאת הנבואה:**
@71 **אמר** נאם בלעם בנו בעור ונאם הגבר פתוח העין נאם שומע אמרי אל אשר יחזה מחזה מאת השם יתעלה והוא גלוי עינים בעת הנבואה ואף עלפי שהוא נופל מרוב התבודדות או ירצה בגלוי עינים עיני לבו והביאור הראשון נראה לנו יותר כי ידמה שבהקיץ היתה מגעת לו הנבואה ולזה אמר אולי יקרה יי' לקראתי בדרך. ואנכי אקרה כה כי האדם לא יישן כשירצה ותכף שיישן לא יחוייב שתגיע לו הנבואה עם שהישרת הקרבנות להגיע אליו הנבואה תצטרך להגיעה בהקיץ לא בעת השינה כי אז ימצא התבודדות בזולת השתדלות כמו שביארנו בב' מספר מלחמות השם. מה טובו אהליך יעקב. ר"ל שגם בקבוץ אשר באהל אהל לא ימצא רק טוב כ"ש בקבוץ כלל ישראל ואמר זה לפי שאם ימצא רע באהל אחד מהם יענשו כלם כמו שביארנו בפרשת קרח והיה זה כן מצד היותם כולם מתאחדים ומזה גם כן אפשר שנתיש בלק וכוין להחטיא קצתם כי בחטא אחד מהם יענשו כלם הנה עניין ישראל והסתעפות זרעו דומה לנחלים שנטיו ונתפשטו מימיהם במקומות רבים שלא יכזבו מימיהם כי בסורם יעמדו אחרים תחתיהם דומים לראשונים וכן הענין בישראל כי במות האבות יקומו אחריהם בניהם וילכו בדרכי אבותיהם לעבוד השם יתעלה וכדי שלא יחשוב חושב שיתחייב מזה שלא ירבו ישראל יותר ממה שהיו אז אמר שהם כגנות אצל נחר שיצמיחו זרועיהם ויפרו וירבו תמיד והנה עשה שנית משל אחר דומה לזה ואמר שהם כאהלים ינטע יי' והם השמים הנטוים ומקיפים בכל הארץ להורות על הנצחיות והקיום לישראל ולפי שאן השמים פרים ורבים שב להמשילם עוד לארזים שהם אצל מים שהם אילנות גדולות ופרים ורבים תמיד מצד רוב המצא המזון להם וכל כך ימצא להם המזון שצמחו בו עד שמדליותיו יזל מים וזרע אחר שיפול אחד אחד מהדליות יהיה גם כן במים רבים וזה לאות שהאבות והבנים ובני הבנים והנמשך להם כלם יהיו בזאת ההצלחה עד שהמלך שהמליכו ישראל והוא שאול ירום מאגג מלכו כי הוא ינצח אותו במלחמה ותנשא מלכותו מאד וזה מבואר מעניין מלכות שאול לפי מה שנזכר בספר שמואל והנה כל זאת הצלחה תהיה לישר' מצד ההשגחה הפרטית אשר תדבק בהם מהאל שהוציא אותם מארץ מצרים לא באמצעות שפע הכוכבים אבל מצד תקפו וגבורתו לעשות מה שירצה ולזה הוציאם משם באותות ומופתים גדולים והוא ישחית הגוים שהם אויבי ישראל וישבר עצמותיהם ויפרקם וכל אחד מחציו יכה בהם ר"ל שמינים רבי מהרעות יביא על אויביהם לפי מה שירצה כעת מה ולזה אין דרך להשמר ממנו כי אין מדרכו להביא רע מיוחד שאם היה זה כן היה זה דרך להשמר ממנו ומשל כי מי שיודע שאויבו אינו מזיק כי אם באש הנה יוכל לקחת עצה מזה להמציא אצלו הדברי המכבים האש אבל אם לא ידע באיזה מין יזיקוהו לא יוכל לקחת עצה על זה. גם בעת שישכון ישראל בטח ולא ילחם הנה מי שילך אליו להלח' בו ימצאהו כארי וכלביא שלא יוכל אחר להסירו ממקומו. ואמנם אמר זה כי היושבים בטח ושלום להם מכל עבריהם אינם מורגלים בענייני המלחמה ולזה אינם בקיאים בה במדרגת בקיאות מי שדרכו להלחם תמיד.
@71 וקודם שנזכור התועלות המגיעות ממנה נזכיר ספק אחד בעניין זאת הפרשה והוא איך נזכרה נבואת בלעם וספור דברי בלק עמו בתורה. כ"ש שיתחזק זה הספק מצד מה שמצאנו שכבר היה בלעם קוסם ונאמר שכבר נזכר זאת הפרשה בזה המקו' מצד התועלות המגיעות ממנה כי כבר יתבאר ממנה עוצם השגחת השם יתעלה על ישראל כמו שביארנו ולזה אמר הנביא עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור מן השטים ועד הגלגל ובזה גם כן תועלת להודיע מה היתה הסבה בזנות ישר' אחר העריות ואחר עבודת זרה ולמה נצטוו ישראל להרוג את המדינים. וראוי שתדע שאלו הספורים מבלק ומבלעם ידעם כלם משה רבינו ע"ה מפי הגבורה ולא נודעו לו אחר הפרסום כי בזולת זה לא היה ראוי שיכתבו בתורה. הנה כמו שהגיד משה מפי הגבורה דבר הספורים שבאו בספר בראשית כן הגיד זה הספור אשר בזה המקום מפי הגבורה ומזה האופן נתאחדו הספורים עם המצות בתורה לפי שהם כלם מכוני' להביא אל השלמת האנושי הנמשכים לדברי התורה ואל זה כוונו ז"ל באמרם שמשה כתב פרשת בלעם.

@71 **ואולם התועלות המגיעות מזאת הפרשה הם י"ו:**
@71 **התועלת** הראשון הוא להודיע שלא יגונה מי שיפחד לנפשו מאחר אם יבקש סבות בהצלתו באי זה אופן שיוכל ולזה תמצא שלא נענשו המואבים במה שהשתדלו להחטיא ישראל לפי שיראתם ופחדתם פן ישחיתם ישאל היתה הסבה בזה כי כבר היו יראים מאד מישראל כמו שאמר ויגר מואב מפני העם מאד כי רב הוא ולזה נחשב למואב החטיאם ישראל אחד מכלי המלחמה ואמנם המדינים שלא היו יריאים מהן וכונו בדבר בלעם למסר מעל ביי' רצה השם יתעלה שיקחו ישראל נקמתם מהם:
@71 **התועלת** השני הוא להודיע עוצם ההבדל שיש בין נביאי ישראל ובין נביאי אומות העולם וזה שכבר הכיר מזה הספור מתכונות בלעם שהוא היה רודף אחר הכבוד ומבקש אותו והפך זה תמצא בנביאי ישראל עד שמשה עם היותו מלך ונביא ספרה התורה שהוא עניו מאד מכל האדם ותמצא גם כן מתכונות בלעם שיה הומה לאסיפת הקנינים וזה יתבאר ממה שאמר אם יתן לי בלק מלא ביתו כסף וזהב כי לולי זה העניין נכסף לו לא אמר זה המאמר והפך זה תמצא בנביאי ישראל וזה יתבאר לך מדבר אלישע לנעמן ואמר אברהם אם מחוט ועד שרוך נעל ואם אקח מכל אשר לך ואף על פי שזכה בו בדין ותמצא גם כן מתכונות בלעם שלא היה נכנע למה שצוהו השם יתעלה בנבואה ולזה הוצרך השם יתעלה להפחידו על ידי המלאך שכבר יהרגהו אם יעבור על דברו לומר כי אם הדבר אשר השם יתעלה ישים בפיו ותמצא גם כן מתכונותיו שהיה נמשך לתאוות חוש המישוש אשר הוא חרפה לנו כי היות הדבר ההוא בלתי מרוחק אצלו לא נתן עצה להפקיר הנשים בכלל לישראל ובכל הנה נביאי ישראל ישתדלו להישיר האנשים לעבודת השם יתעלה ולשמרם מהחטא והמרי ובלעם היה מישיר אותם בעצתו אל החטא והמרי עם היות כחו יפה מאד בנבואה בזה העת עד שהיתה מגעת לו הנבואה בהקיץ כמו שביאר' ומזה הצד אמרו רבותינו ז"ל על אמרו ולא קם נביא עוד בישראל כמשה אבל באומ' העולם קם ומאי ניהו בלעם ואמרו זה על צד ההפלגה עם טוב הכנתו בנבואה עד שנתקרבה מדרגתו למדרגת משה רבינו בדרך שהית' מגעת לו בהקיץ בדבר שרצה להגיע לו הנה תמשמש בהכנתו בפחיתיות לא להישיר האנשים אל הטוב וגם לא קנה לעצמו המדות הראויות לשלם וראוי שתדע שכבר נתחייב מלשון התורה במה שאמרה ולא קם נביא עוד בישראל כמשה שנאמ' אבל באומות העלם קם ואם לא הנה יהיה אמרו בישראל לבטלה אבל לא יתחייב שיהיה זה הקם באומות העולם בלעם כי לא היה במשה באחד מהדברים שזכרה התורה בזה המקו' שלא קם בהם נביא כמוהו כי לא ידע ה' ית' בלעם פנים בפנים ולא חדש אותות ומופתים כלל כל שכן שלא חדשם במדרגת האותות והמופתים שנעשו מאת הש"י ע"י מש רבינו ואמנם האמת יהיה המתחייב מהפסוק הזה שלא קם נביא עוד כמשה שהיה נביא בישראל לבד אבל יהיה שיהיה עם זה נביא באומו' העולם ג"כ הוא מלך המשיח כמו שאמרו במדרש הנה ישכיל עבדי שכבר יהיה יותר גדול ממשה ויתבאר שנפלאותיו ג"כ תהיינה למעלה מופלאות משה כי משה משך ישראל לבד לעבודת שם ית' בנפלאות שחדש והוא ימשוך כל האומות לעבודת השם ית' באמרו אז אהפוך אל עמים שפה ברורה לקרוא כלם בשם יי' וזה אמנם יהיה באמצעות מופת נפלא יראה בקצות הארץ לכל האומות והוא תחיית המתים:
@71 **התועלת** השלישי הוא להודיע עוצם השגחת השם ית' על ישראל במה שהשתדל לשמור בלעם שלא יקללם בזה אופן הנפלא שספרה התרה עד שעם תשות בלעם לקלל אותם הוכרח להשמר מזה מצד מצות ה' ית' ופחדו שפיל עליו בדבר המלאך שהראה לו בדרך וחרבו שלופה בידו וכבר יסופק על זה למה השתדל הש"י כל זה ההשתדלו' שלא יאור בלעם העם אחר שהש"י אמ' שהוא ברך התזיק להם קללת בלעם ואם אמרנו שעשה זה הש"י להציל בלעם מהבשת איך היה זה העניין על צד החסד לישראל כמו שנראה מדברי הנביא באמרו עמי זכור מה יעץ בלק מלך מואב ואם אמרנו שהש"י עושה זה לפי שגלוי היה וידוע לפניו שישראל היו ממרים את פיו תמיד והיה הש"י כועס עליהם וממית מהם במגפה או בזולת זה כמו שנזכר בתורה ואם היה בלעם מקלל אותם ויקרה להם אחר זה המקרה זה היה חושב בלעם ומוא' שקללתו סבב להם זה הנה עדין ישאר הספק בעינו כי בזה לא יהיה חסד לישראל כשלא קללם אך יהיה בו כבוד לש"י שלא יתפאר בלעם כי קללתו סבב להן זה ואולם התר זה הספק יש בו מהקושי העצו' לפי מה שאחשוב והנראה לי בזה הוא אם שנאמר שהש"י עשה זה לסבה שכאשר יחטאו ויכסה ש"י על צד התוכחת ירגישו כי חטאם היה סבה אל זה העונש הבא עליהם ויחיה זה סבה אל שישובו אל הש"י וריחמם ואם היה בלעם מקלל אותם הנה לרוב הפרסום שהיה בעניינו שאשר יאור יואר הנה יתלו ישר' העונש הבא אליהם אם שיהיה מפני קללה שקללן בלעם ולא ישתדלו לשוב אל הש"י ויהיה זה סבה שיחר אף השם בהם ויכלם. והמשל כי לא לו קללם בלעם הנה בבא המגפה בעדת הש"י על דבר פעור לא היו משתדלי' לשוב אל הש' ולהתנחם מחטאם לחשבם שקללת בלעם ישר' תסבב זה ואם אמר אומ' איך ידעו ישראל זה העניין ר"ל אם קלל אותם בלעם עד שיצטרך ה' לשמרו מלקללם לזאת הסב' אמרנו לו שכבר אפשר זה מפני רוב התמדת' אצל בני מואב כי אצלם היו יושבים ולשגלם עם נשותיהם ולזה יתכן שיספרו להם זה בני מואב להחטיאם יותר ויקרה מזה ליש' מההיזק מה שכבר זכרנו או נאמ' שקללת בלעם האנשי' היה בעשותו מיני כשוף ונחש להמציא להם היזק והם דברים מכחישים פמליא של מעלה והנה רצוני באמרי נחש הנחש המתיחס לכשוף כמו שידמו הסכלים שכבר נודע על דרך נסיון שעשיית תמונת כך מדבר כך בעת כך בתנאים כך מהככבים תזיק לאבר כך או לדבר כך והיה זה חלק גדול מחכמי מצרים וחכמי בכל והנה היה נעזר בזה בלעם מהודעה שתגיע לו בקסם לדעת באי זה מהדברים יתכן שיוזק האיש ההוא או העם ההוא לפי מה שיתבאר לו בקסם שימשך לאי ההוא או לעם ההוא משפע הככבים ולפי שהיה אפשר שימצא באלו הענינים או במה שהוא מסוגם מה שאפשר שיתחדש בו היזק לישראל רצה השם יתעלה להצילם מזה ואף על פי שמהענינים האלו לא יוזק מי שתדבק בו השגחת השם יתעלה כי גם במה שנתחייב בעצמות וראשונה מצד מערכת הככבים ישמרהו השם כמו שביארנו בד' מספר מ"י הנה מפני שישראל לא היו אז באופן מהשלמות שתדבק בהם כמו זאת ההשגחה ויורה על זה התפתותם בקלות לעריות ולע"ז הצטרך הש' יתעלה לשמרם מזאת הקללה:
@71 **התועלת** הד' הוא להודיע שהעלאת העולות הוא ממה שיישיר להגעת הנבואה הלא תראה שבזולת זה היה צריך בלעם כשירצה להגיע לו השפע האלהי להודיע לו הדבר שירצה שימתין שיהיה לילה ואז יהיה לו זאת ההודעה בעת השינה בעת אחד מן הלילה לא בעת מוגבל ממנו ולזה אמר לינו פה הלילה וגומר שבו נא בזה גם אתם הלילה ואמנם עם הקרבת העולות נתחדשה לו ההודעה בהקיץ וכאשר רצה ולזה צוהו השם יתעלה על הקרבתם כמו שביארנו:
@71 **התועלת** הה' בדעו' והוא להודיע שכבר יצטרך לנביא שתתבודד מחשבתו במי שירצה שתגיע לו בנבואה ההודעה מעניניו ולזה ספר בזה המקום שהקפיד בלעם בפעם בפעם שיראה העם אשר רצה שתגיע לו בנבואה ההודעה בעניניהם:
@71 **התועלת** הו' הוא בדעות והוא להודיע שמי שתדבק בו ההשגחה האלהית לא יוזק בכשוף ובמה שיונהג מנהגו ולזה אמר בלעם כשרצה לבאר שקללתו לא תזיק לישראל שהשם יתעלה לא הסכים לקלל את העם כי זה העם נתייחד מבין שאר האומות בשהוא דבק בשם יתעלה ודורך אל החיים הנצחיים וזהו אמרו הן עם לבדד ישכון ובגוים לא יתחשב להעיר על התכלית שישראל פונה אליו לאור באור החיים תמות נפשי מות ישרים ותהי אחריתי כמהו:
@71 **התועלת** הח' הוא בדעות והוא להודיע שאין כח בנחש ובקסם להודיע הדברי' העתידים למי שתדבק בו ההשגחה לפי שענייניהם בלתי מסודרים משפע הכוכבים וזהו אמרו כי לא נחש ביעקב ולא קסם בישראל ולזה גם כן לא הלך בפעם כפעם לקראת נחשים אך הנבואה תודיע זה כי היא מסודרת מהשכל ושופעת ממנו כמו שביארנו בשני מספר מ"י ולזה תמצא שהודיע השם יתעלה לאברהם האותות והמופתים שיתחדשו על דרך ההשגחה הפרטית בעת יציאת ישראל ממצרי' למשכם לעבודתו ולזה אמר לו וגם את הגוי אשר יעבודו דן אנכי ולזה קרא בספר ישעיה שם השם יתעלה פלא יועץ ר"ל שהוא מודיע הפלאים טרם בואם זמן ארוך והנה בזה עיון חזק לא יכיל ביאורו זה הספר:
@71 **התועלת** הט' הוא במצות והוא שכבר למדנו מזה שהדם נקרא משקה אשר ישתה למה שאמר ודם חללים ישתה וזה שאין ראוי שנבין אומרו כל משקה אשר ישתה אשר ראוי שישתה לפי משפטי התורה שאין הטומאה בדברים יותר מפני היותם ראוים למאכל ולמשתה לפי משפטי התורה אבל הענין הוא בהפך שהבהמה הטהורה שנשחטה טהורה מלטמא ואין הענין כן בבהמה הטמאה ולזה הוא מבוא שאמרו אשר ישתה הרצון בו שיהיה מצד עצמות וראוי לשתות ולזה יתבאר שהדם מקבל טומאה כי הוא ראוי לשתות מצד עצמות שנאמר ודם חללים ישתה:
@71 **התועלת** הי' הוא להודיע אמתת הנבואה כי בלעם נתנבא בכמה דברים כבר נתחדשו ויצאו אל הפעל כמו שיתבאר מדברי ביאורינו זאת הפרשה:
@71 **התועלת** הי"א הוא להודיע ענין ביאת מלך המשיח אשר אנחנו מקוים תמיד בו כמו שאמר דרך ככב מיעקב וגו'. כי לא היה מיעקב מי שהרס ורמס כל האומות עדיין ולזה יחוייב שנודה שעליו אמר זה:
@71 **התועלת** הי"ב הוא להודיע שעברה גוררת עברה הלא תראה כי מזנות העם אל בנות מואב נמשך להם שאכלו מזבחי ע"ז והשתחוו לע"ז ולזה ראוי לכל אדם להשמר מעבירה קלה כמו השמרו מהחמורה כי הקלה תביא אליה:
@71 **התועלת** הי"ג הוא להודיע כי כאשר התחל לצמוח רע מה ראוי להשתדל להסירו תכף בלי שום עצלה כדי שלא יצמח יותר לה צוה השם יתעלה למשה שירבה השופטים לישראל להרוג תכף כל הנמצדים לבעל פעור כדי שישיב אפו מישראל וצוה לעשות זה לעיני השמש כדי שיוסרו כל ישראל ויסורו זה הרע מהם לגמרי:
@71 **התועלת** הי"ד הוא במדות והוא להודיע רוע תכונת זמרי שעם ראותו ההרג כל הנמצדים לבעל פעור והיה המגפה בעם ה' על זאת העבירה לא נמנע מלהחזיק בה עד שבפרהסיא הביא המדינית במחנה ישראל והביאה לאהלו להזקק לה תכף אם לרוב רתיחת טבעו והתגבר יצרו הרע עליו אם שכיון להכעיס ולמרות דבר השם יתעלה:
@71 **התועלת** הט"ו הוא להודיע שבועל בת אל נכר מותר להרגו בשעת מעשה ולזה ספר שפנחס דקר את שניהם בשעת מעשה באופן שנתבאר לכל שהם היו נזקקין אז זה לזה:
@71 **התועלת** הי"ו הוא שבכל מקום שיש בו חול השם יתעלה אין חולקן כבוד לרב אבל כל הקודם להסיר המכשול זכה ולזה תמצא שעם היות משה רבינו בזאת המדרגה הנפלאה שהיה בה מהמעלה והשלמות הנה לא לקח פינחס רשות ממנו על זה המעשה אבל התעורר מעצמו לבער הרע בזריזות רב ושם נפשו להרוג נשיא שבט ישראל לקנאתו לאלהיו וכבר היה לו מזה גמול טוב מהש' יתעלה שנתן בריתו אתו החיי' והשלום וזכה להיות מזרעו כהנים גדולים רבים והנה מצאנו לו מארך חיים שכבר היה חי בימי פלגש בגבעה אמר ופנחס בן אלעזר בן אהרן הכהן עומד לפניו בימים ההם גם היה חי בימי דוד אמר ופנחס בן אלעזר בן אהרן נגיד היה עליהם לפני יי' ואמו רז"ל שעדיין הוא חי ויחיה עד תחית המתים ולזה הסכימו שפנחס הוא אליהו כי נמצא לו ארך חיים נפלא כמו שאמר מלאכי הנה אני שולח לכם את אליה הנביא וגומר. והנראה בעינינו שהענין הוא כמו שנזכור הטעם בביאור מלכים בג"ה:
